prompt --application/shared_components/logic/application_processes
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(5937935774535702357)
,p_process_sequence=>2
,p_process_point=>'AFTER_LOGIN'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set time zone'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    c integer := 0;',
'begin',
'    for c1 in (',
'       select timezone_preference',
'       from   eba_proj_tz_pref',
'       where  username = upper(:APP_USER)) loop',
'       --',
'       if c1.timezone_preference is not null then',
'           c := c + 1;',
'           APEX_UTIL.SET_SESSION_TIME_ZONE (P_TIME_ZONE => c1.timezone_preference ); ',
'       end if;',
'       exit;',
'    end loop;',
'    if c = 0 then',
'        if apex_util.get_session_time_zone is null then',
'            APEX_UTIL.SET_SESSION_TIME_ZONE (P_TIME_ZONE => ''US/Pacific''); ',
'        end if;',
'    end if;',
'end;'))
);
end;
/
prompt --application/shared_components/logic/application_processes
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(6682610062167689903)
,p_process_sequence=>3
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set counts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    function fmt (p_number in number default 0) return varchar2',
'    as ',
'    begin',
'         if p_number >= 1000000 then',
'            return trim(to_char(trunc(p_number/1000000),''999G999G999G990''))||''M'';',
'         elsif p_number >= 1000 then',
'            return trim(to_char(trunc(p_number/1000),''999G999G999G990''))||''K'';',
'         else',
'            return trim(to_char(p_number,''999G999G999G990''));',
'         end if;',
'    end fmt;',
'begin',
'for c1 in (select count(*) c from EBA_PROJ_STATUS_FILES) loop',
'   :attachments := fmt(c1.c);',
'end loop;',
'',
'for c1 in (',
'select count(*) c  ',
'from eba_proj_status p, EBA_PROJ_STATUS_CODES s ',
'where p.PROJECT_STATUS = s.id(+) ',
'      and nvl(IS_CLOSED_STATUS,''N'') != ''Y'') loop',
'    :PROJECTS := fmt(c1.c);',
'end loop;',
'',
'for c1 in (select count(*) c  from eba_proj_status_ms) loop',
'    :MILESTONES := fmt(c1.c);',
'end loop;',
'for c1 in (select count(*) c  from eba_proj_status_ais) loop',
'    :AI := fmt(c1.c);',
'end loop;',
'for c1 in (select count(*) c  from EBA_PROJ_STATUS_RPTS) loop',
'    :SR := fmt(c1.c);',
'end loop;',
'for c1 in (select count(*) c  from eba_proj_status_updates) loop',
'    :UPDATES := fmt(c1.c);',
'end loop;',
'end;'))
,p_process_when_type=>'NEVER'
);
end;
/
prompt --application/shared_components/logic/application_processes
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(15187394442744295539)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PROFILE_PHOTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if apex_authentication.is_authenticated then ',
'        apex_debug.message(''user is authed'', p_force => true);',
'        apex_debug.message(wwv_flow.g_user, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_USERNAME, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_SESSION_ID, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_SESSION_ID_FROM_COOKIE, p_force => true);',
'    else ',
'        apex_debug.message(''user is not authed'', p_force => true);',
'        apex_debug.message(wwv_flow.g_user, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_USERNAME, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_SESSION_ID, p_force => true);',
'        apex_debug.message(APEX_CUSTOM_AUTH.GET_SESSION_ID_FROM_COOKIE, p_force => true);',
'    end if; ',
'',
'    for c1 in ( select photo_blob,',
'                    photo_name,',
'                    photo_mimetype,',
'                    dbms_lob.getlength(photo_blob) len',
'                from eba_proj_status_users',
'                where upper(username) = upper(:GET_ID) ) loop',
'        if c1.len > 0 then',
'            sys.htp.init();',
'            sys.owa_util.mime_header(',
'                nvl(c1.photo_mimetype, ''application/octet''),',
'                false',
'            );',
'            sys.htp.p(''Cache-Control: max-age=36000'');',
'            sys.htp.p(''Content-Length: '' || c1.len);',
'            sys.htp.p(''Content-Disposition: inline; filename="''',
'                ||apex_escape.html(c1.photo_name)|| ''"; filename*=UTF-8''''''''''',
'                ||apex_escape.html(c1.photo_name));',
'            sys.owa_util.http_header_close;',
'            sys.wpg_docload.download_file(c1.photo_blob);',
'            apex_application.stop_apex_engine;',
'        else',
'            apex_util.redirect_url(''#APP_IMAGES#no-photo.png'');',
'        end if;',
'    end loop;',
'end;'))
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(6047225760533677391)
,p_process_sequence=>1
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Trim All Page Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for c1 in (select item_name',
'               from apex_application_page_items',
'               where application_id = :APP_ID',
'                   and page_id = :APP_PAGE_ID',
'                   and display_as_code in (''NATIVE_TEXT_FIELD'',',
'                                           ''NATIVE_TEXTAREA'',',
'                                           ''NATIVE_NUMBER_FIELD'') ) loop',
'        apex_util.set_session_state( c1.item_name,',
'            regexp_replace(apex_util.get_session_state( c1.item_name ),',
'                ''^[[:space:]]*(.*?)[[:space:]]*$'', ''\1''',
'            )',
'        );',
'    end loop;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
