prompt --application/shared_components/plugins/item_type/com_oracle_apex_flex_field
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(6118735455485368961)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'COM.ORACLE.APEX.FLEX_FIELD'
,p_display_name=>'Flex Field'
,p_supported_ui_types=>'DESKTOP:JQM_SMARTPHONE'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','COM.ORACLE.APEX.FLEX_FIELD'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'type t_flex_config is record (',
'    is_active         boolean,',
'    form_label_text   varchar2(255),',
'    is_required       boolean,',
'    display_as        varchar2(255),',
'    flexible_column   varchar2(128),',
'    lov_sql_query     varchar2(32767),',
'    width             number,',
'    max_width         number,',
'    height            number,',
'    label_template_id number,',
'    help_text         varchar2(4000),',
'    label_alignment   varchar2(30),',
'    format_mask       varchar2(30),',
'    default_value     varchar2(4000),',
'    rpt_hdr_alignment varchar2(30)',
'    );',
'',
'--===============================================================================',
'-- Reads the config of a flex field.',
'--===============================================================================',
'function get_flex_config (',
'    p_item   in apex_plugin.t_page_item,',
'    p_plugin in apex_plugin.t_plugin )',
'    return t_flex_config',
'is',
'    -- Use named constants instead of the generic attribute variables',
'    c_config_table constant varchar2(30) := p_plugin.attribute_01;',
'    --',
'    l_flex_table     varchar2(255);',
'    l_flex_column    varchar2(255);',
'    l_is_active_yn   varchar2(1) := ''N'';',
'    l_is_required_yn varchar2(1);',
'    l_flex_config    t_flex_config;',
'begin-- Get the information which flex table and column is processed',
'    begin',
'        select',
'               p.process_source,',
'               i.item_source',
'          into l_flex_table,',
'               l_flex_column',
'          from apex_application_page_proc p,',
'               apex_application_page_items i',
'         where p.application_id    = apex_application.g_flow_id',
'           and p.page_id           = apex_application.g_flow_step_id',
'           and p.process_type_code = ''DML_FETCH_ROW''',
'           and i.application_id    = apex_application.g_flow_id',
'           and i.page_id           = apex_application.g_flow_step_id',
'           and i.item_id           = p_item.id',
'           and i.item_source_type  = ''Database Column'';',
'    exception',
'        when no_data_found then',
'            l_flex_table  := null;',
'            l_flex_column := null;',
'    end;',
'',
'    --',
'    -- Only do the following if we have a flex table and flex column value',
'    if l_flex_table is not null and l_flex_column is not null then',
'        --',
'        -- Get the table name out of the "DML Fetch" process source. The format is',
'        -- F|#OWNER#:DEMO_ORDERS:P29_ORDER_ID:ORDER_ID',
'        l_flex_table := substr(l_flex_table, 11);',
'        l_flex_table := substr(l_flex_table, 1, instr(l_flex_table, '':'') -1);',
'        --',
'        -- Read the flex table configuration',
'        begin',
'            execute immediate ''select /*+ result_cache */ '' ||',
'                              ''active_yn, form_label_text, is_required_yn, display_as, lov_sql_query, width, '' ||',
'                              ''max_width, height, label_template_id, flexible_column, help_text, '' ||',
'                              ''label_alignment, format_mask, default_value, rpt_hdr_alignment'' ||',
'                              ''  from '' || sys.dbms_assert.enquote_name(c_config_table) ||',
'                              '' where flexible_table  = :p_flex_table'' ||',
'                              ''   and flexible_column = :p_flex_column''',
'                         into l_is_active_yn,',
'                              l_flex_config.form_label_text,',
'                              l_is_required_yn,',
'                              l_flex_config.display_as,',
'                              l_flex_config.lov_sql_query,',
'                              l_flex_config.width,',
'                              l_flex_config.max_width,',
'                              l_flex_config.height,',
'                              l_flex_config.label_template_id,',
'                              l_flex_config.flexible_column,',
'                              l_flex_config.help_text,',
'                              l_flex_config.label_alignment,',
'                              l_flex_config.format_mask,',
'                              l_flex_config.default_value,',
'                              l_flex_config.rpt_hdr_alignment',
'                        using l_flex_table, l_flex_column;',
'        exception when no_data_found then',
'            l_is_active_yn := ''N'';',
'        end;',
'    end if;',
'    --',
'    l_flex_config.is_active   := ( l_is_active_yn = ''Y'' );',
'    l_flex_config.is_required := ( l_is_required_yn = ''Y'' );',
'    --',
'    return l_flex_config;',
'    --',
'end get_flex_config;',
'',
'--===============================================================================',
'-- Renders a flex field based on the configuration in the flex field repository table.',
'--===============================================================================',
'function render (',
'    p_item                in apex_plugin.t_page_item,',
'    p_plugin              in apex_plugin.t_plugin,',
'    p_value               in varchar2,',
'    p_is_readonly         in boolean,',
'    p_is_printer_friendly in boolean )',
'    return apex_plugin.t_page_item_render_result',
'is',
'    l_name           varchar2(30);',
'    l_item           apex_plugin.t_page_item := p_item;',
'    l_result         apex_plugin.t_page_item_render_result;',
'    l_flex_config    t_flex_config;',
'    l_label_template varchar2(30);',
'    l_date_picker    varchar2(10000);',
'    l_label          varchar2(32767);',
'    l_label_col_span number := 3;',
'    l_help_text      varchar2(4000);',
'    l_format_mask    varchar2(30);',
'    function get_format_mask(',
'        p_item_id in     number,',
'        p_app_id  in     number,',
'        p_page_id in     number',
'    ) return varchar2',
'    is',
'        l_format_mask    varchar2(30);',
'    begin',
'        select',
'            format_mask',
'        into',
'            l_format_mask',
'        from',
'            apex_application_page_items',
'        where',
'            item_id = p_item_id',
'        and',
'            application_id = p_app_id',
'        and',
'            page_id = p_page_id;',
'        return l_format_mask;',
'    exception',
'        when no_data_found then',
'            l_format_mask := null;',
'    end get_format_mask;',
'    function get_help_text(',
'        p_item_id in     number,',
'        p_app_id  in     number',
'    ) return varchar2',
'    is',
'        l_help_text    varchar2(4000);',
'    begin',
'        select',
'            item_help_text',
'        into',
'            l_help_text',
'        from',
'            apex_application_page_items',
'        where',
'            item_id = p_item_id',
'        and',
'            application_id = p_app_id;',
'        return l_help_text;',
'    exception',
'        when no_data_found then',
'            l_help_text := null;',
'    end get_help_text;',
'begin',
'    l_flex_config := null;',
'    l_flex_config := get_flex_config (',
'                         p_item   => l_item,',
'                         p_plugin => p_plugin );',
'    --',
'    -- Don''t render the flex field if it''s not active',
'    if not l_flex_config.is_active then',
'        l_result.is_navigable := false;',
'        return l_result;',
'    end if;',
'    --',
'    -- Always assign the item''s required setting value to the flex field''s required setting value',
'    l_item.is_required := l_flex_config.is_required;',
'    --',
'    -- If a page item saves state, we have to call the get_input_name_for_page_item',
'    -- to render the internal hidden p_arg_names field. It will also return the',
'    -- HTML field name which we have to use when we render the HTML input field.',
'    l_name := apex_plugin.get_input_name_for_page_item(false);',
'    --',
'    case l_flex_config.display_as',
'        when ''TEXT''        then',
'            sys.htp.prn(',
'                ''<input type="text" name="'' || l_name || ''" '' ||',
'                ''size="'' || l_flex_config.width || ''" maxlength="'' || l_flex_config.max_width || ''"'' ||',
'                ''value="'' || apex_escape.html_attribute(nvl(p_value, l_flex_config.default_value))||''" '' ||',
'                apex_plugin_util.get_element_attributes (',
'                    p_item          => l_item,',
'                    p_default_class => ''text'' ) ||',
'                ''/>'');',
'',
'        when ''TEXTAREA''    then',
'            sys.htp.prn(',
'                ''<textarea name="'' || l_name || ''" '' ||',
'                ''cols="'' || l_flex_config.width || ''" rows="'' || l_flex_config.height || ''" maxlength="'' || l_flex_config.max_width || ''" wrap="virtual" '' ||',
'                apex_plugin_util.get_element_attributes (',
'                    p_item          => l_item,',
'                    p_default_class => ''textarea'' ) ||',
'                ''>'');',
'            apex_plugin_util.print_escaped_value(nvl(p_value, l_flex_config.default_value));',
'            sys.htp.prn(''</textarea>'');',
'',
'        when ''SELECT_LIST'' then',
'            wwv_flow_utilities.show_as_combobox (',
'                p_lov        => l_flex_config.lov_sql_query,',
'                p_null_text  => ''- select value -'',',
'                p_null_value => null,',
'                p_show_extra => ''NO'',',
'                p_value      => nvl(p_value, l_flex_config.default_value),',
'                p_name       => l_name,',
'                p_attributes => apex_plugin_util.get_element_attributes (',
'                                    p_item          => l_item,',
'                                    p_default_class => ''selectlist'' )',
'                );',
'',
'        when ''NUMBER''      then',
'            l_format_mask := get_format_mask(l_item.id, apex_application.g_flow_id, apex_application.g_flow_step_id);',
'            --',
'            -- Update the format mask of the page item',
'            if nvl(l_flex_config.format_mask,''xxx'') <> nvl(l_format_mask,''xxx'') then',
'                apex_app_builder_api.edit_page_item (',
'                    p_page_id             => apex_application.g_flow_step_id,',
'                    p_item_name           => p_item.name,',
'                    p_format_mask         => l_flex_config.format_mask);',
'            end if;',
'            sys.htp.prn(',
'                ''<input type="text" name="'' || l_name || ''" '' ||',
'                ''size="'' || l_flex_config.width || ''" maxlength="'' || l_flex_config.max_width || ''"'' ||',
'                ''value="'' || apex_escape.html_attribute(trim(nvl(p_value, l_flex_config.default_value))) || ''" '' ||',
'                apex_plugin_util.get_element_attributes (',
'                    p_item          => l_item,',
'                    p_default_class => ''number_field'' ) ||',
'                ''/>'');',
'',
'        when ''DATE''        then',
'            l_format_mask := get_format_mask(l_item.id, apex_application.g_flow_id, apex_application.g_flow_step_id);',
'            --',
'            -- Update the format mask of the page item',
'            if nvl(l_flex_config.format_mask,''xxx'') <> nvl(l_format_mask,''xxx'') then',
'                apex_app_builder_api.edit_page_item (',
'                    p_page_id             => apex_application.g_flow_step_id,',
'                    p_item_name           => p_item.name,',
'                    p_format_mask         => l_flex_config.format_mask);',
'            end if;',
'            l_date_picker := wwv_flow_utilities.get_date_picker (',
'                p_id                    => p_item.name,',
'                p_name                  => l_name,',
'                p_value                 => nvl(p_value, l_flex_config.default_value),',
'                p_date_format           => l_flex_config.format_mask,',
'                p_size                  => l_flex_config.width,',
'                p_max_length            => l_flex_config.max_width,',
'                p_attributes            => apex_plugin_util.get_element_attributes (',
'                                                p_item          => l_item,',
'                                                p_default_class => ''datepicker''',
'                                            )',
'            );',
'            sys.htp.prn(l_date_picker);',
'        else',
'            sys.htp.prn(''<!-- ERRROR IN FLEX FIELD PLUGIN: l_flex_config.display_as = "''||nvl(l_flex_config.display_as,''???'')||''" -->'');',
'    end case;',
'',
'    -- Read label template',
'    begin',
'        select /*+ result_cache */',
'            replace(',
'                replace(',
'                    before_label || l_flex_config.form_label_text || after_label,',
'                    ''#CURRENT_ITEM_NAME#'',',
'                    p_item.name),',
'                ''#LABEL_ID#'',p_item.name||''_LABEL''',
'            )',
'        into l_label',
'        from apex_application_temp_label',
'            -- $$$ make it NLS aware',
'        where application_id = apex_application.g_flow_id',
'            -- $$$ restrict to theme of current UI',
'            and label_template_id = l_flex_config.label_template_id;',
'        exception when no_data_found then',
'            l_label := '''';',
'    end;',
'    -- Deal with column span.',
'    -- This should always return a value, but use the loop construct just in case.',
'    for c1 in ( select nvl(pi.grid_label_column_span, tp.grid_default_label_col_span) grid_span',
'                from apex_application_pages pg,',
'                    apex_application_temp_page tp,',
'                    apex_application_page_items pi',
'                where pi.application_id= apex_application.g_flow_id',
'                    and tp.application_id = pg.application_id',
'                    and tp.template_name = pg.page_template',
'                    and pg.application_id = pi.application_id',
'                    and pg.page_id = pi.page_id',
'                    and pi.item_id = p_item.id ) loop',
'        l_label_col_span := c1.grid_span;',
'    end loop;',
'    l_label := replace(l_label, ''#LABEL_COLUMN_SPAN_NUMBER#'', to_char(l_label_col_span));',
'',
'    --',
'    -- Handle the help text.',
'    l_help_text := get_help_text(l_item.id, apex_application.g_flow_id);',
'    --',
'    -- Update the help text of the page item',
'    apex_app_builder_api.edit_page_item (',
'        p_page_id             => apex_application.g_flow_step_id,',
'        p_item_name           => p_item.name,',
'        p_item_label          => l_flex_config.form_label_text,',
'        p_help_text           => l_flex_config.help_text',
'    );',
'',
'    --',
'    -- Now that the item''s help text has been updated, ',
'    -- refer to it in the label''s help text',
'    l_label := replace(l_label, ''#CURRENT_ITEM_ID#'', p_item.id);',
'    --',
'    l_label := apex_plugin_util.replace_substitutions(',
'                   p_value  => l_label,',
'                   p_escape => false );',
'',
'    --',
'    -- Change the item label on the fly',
'    --',
'    apex_javascript.add_onload_code(p_code=>''$("label[for='' || p_item.name || '']").parent().replaceWith('' || replace(apex_javascript.add_value(l_label, false),''#VALUE_REQUIRED#'',apex_lang.message(''VALUE_REQUIRED'')) || '');'',',
'                                   p_key=>''flex_upd_''||p_item.name);',
'',
'    -- Tell APEX that this field is navigable',
'    l_result.is_navigable := true;',
'',
'    return l_result;',
'end render;',
'',
'--==============================================================================',
'-- Validate a flex field based on the configuration in the flex field repository table.',
'--==============================================================================',
'function validate (',
'    p_item   in apex_plugin.t_page_item,',
'    p_plugin in apex_plugin.t_plugin,',
'    p_value  in varchar2 )',
'    return apex_plugin.t_page_item_validation_result',
'is',
'    l_result      apex_plugin.t_page_item_validation_result;',
'    l_flex_config t_flex_config;',
'begin',
'    l_flex_config := get_flex_config (',
'                         p_item   => p_item,',
'                         p_plugin => p_plugin );',
'    --',
'    -- Don''t render the flex field if it''s not active',
'    if not l_flex_config.is_active then',
'        return l_result;',
'    end if;',
'    --',
'    if l_flex_config.is_required and p_value is null then',
'        l_result.message := l_flex_config.form_label_text || '' is required!'';',
'    end if;',
'    return l_result;',
'end validate;'))
,p_api_version=>1
,p_render_function=>'render'
,p_validation_function=>'validate'
,p_standard_attributes=>'VISIBLE:SESSION_STATE:SOURCE'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>The Flex Field plug-in renders a flex field based on the configuration in the flex field repository table.</p>',
'<p>You can review how this item plug-in is utilized in P-Track and Customer Tracker.</p>'))
,p_version_identifier=>'5.0.1'
,p_about_url=>'http://apex.oracle.com/plugins'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(4049708253588548947)
,p_plugin_id=>wwv_flow_api.id(6118735455485368961)
,p_attribute_scope=>'APPLICATION'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Flex Registry Table'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_display_length=>30
,p_max_length=>30
,p_is_translatable=>false
,p_help_text=>'Enter the table name which holds the required flex field attributes.'
);
end;
/
prompt --application/shared_components/plugins/region_type/com_oracle_apex_html5_bar_chart
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(6647654913897542324)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.ORACLE.APEX.HTML5_BAR_CHART'
,p_display_name=>'HTML 5 Bar Chart'
,p_supported_ui_types=>'DESKTOP'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','COM.ORACLE.APEX.HTML5_BAR_CHART'),'#IMAGE_PREFIX#plugins/com.oracle.apex.html5_bar_chart/1.0/')
,p_javascript_file_urls=>'#PLUGIN_FILES#com_oracle_apex_html5_bar_chart.js'
,p_css_file_urls=>'#PLUGIN_FILES#com_oracle_apex_html5_bar_chart.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION RENDER (',
'    P_REGION IN APEX_PLUGIN.T_REGION,',
'    P_PLUGIN IN APEX_PLUGIN.T_PLUGIN,',
'    P_IS_PRINTER_FRIENDLY IN BOOLEAN',
') RETURN APEX_PLUGIN.T_REGION_RENDER_RESULT IS',
'BEGIN',
'    HTP.PRN(''<div id="''||APEX_ESCAPE.HTML_ATTRIBUTE(P_REGION.STATIC_ID)||''_chart" class="hbc">'');',
'    HTP.PRN(''</div>'');',
'    ',
'    APEX_JAVASCRIPT.ADD_ONLOAD_CODE (',
'        P_CODE => ''com_oracle_apex_html5_bar_chart(''||',
'            APEX_JAVASCRIPT.ADD_VALUE(P_REGION.STATIC_ID)||',
'            ''{''||',
'                -- Why is this attribute needed if is not used?',
'                APEX_JAVASCRIPT.ADD_ATTRIBUTE(',
'                    ''pageItems'', ',
'                    APEX_PLUGIN_UTIL.PAGE_ITEM_NAMES_TO_JQUERY(P_REGION.AJAX_ITEMS_TO_SUBMIT)',
'                )||',
'                APEX_JAVASCRIPT.ADD_ATTRIBUTE(',
'                    ''ajaxIdentifier'', ',
'                    APEX_PLUGIN.GET_AJAX_IDENTIFIER, ',
'                    FALSE, ',
'                    FALSE',
'                )||',
'            ''}''||',
'        '');''',
'    );',
'    ',
'    RETURN NULL;',
'END RENDER;',
'',
'FUNCTION AJAX (',
'    P_REGION IN APEX_PLUGIN.T_REGION,',
'    P_PLUGIN IN APEX_PLUGIN.T_PLUGIN',
') RETURN APEX_PLUGIN.T_REGION_AJAX_RESULT IS',
'    -- Map region attributes to function constants',
'    -- MODERN, CLASSIC',
'    C_CHART_TYPE CONSTANT VARCHAR2(7) := P_REGION.ATTRIBUTE_15;',
'    -- MODERN, MODERN_2, SOLAR, METRO, CUSTOM, COLUMN',
'    C_COLOR_SCHEME CONSTANT VARCHAR2(8) := P_REGION.ATTRIBUTE_17;',
'    C_CUSTOM_CHART_COLORS CONSTANT VARCHAR2(4000) := P_REGION.ATTRIBUTE_10;',
'    C_COLOR_COLUMN CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_19;',
'    -- NONE, IMAGE, ICON, INITIALS',
'    C_ICON_TYPE CONSTANT VARCHAR2(8) := case when C_CHART_TYPE = ''ICON'' then P_REGION.ATTRIBUTE_01 end;',
'    C_LABEL_COLUMN CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_02;',
'    C_LABEL_LINK CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_03;',
'    C_VALUE_COLUMN CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_04;',
'    C_VALUE_LINK CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_05;',
'    -- ABOVE, AROUND',
'    C_TEXT_POSITION VARCHAR2(6) := P_REGION.ATTRIBUTE_18;',
'    C_CHART_CSS_CLASSES CONSTANT VARCHAR2(32767) := P_REGION.ATTRIBUTE_06;',
'    C_IMAGE_URL CONSTANT VARCHAR2(4000) := P_REGION.ATTRIBUTE_07;',
'    C_CSS_ICON_CLASS_NAME CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_08;',
'    C_INITIALS_COLUMN CONSTANT VARCHAR2(255) := P_REGION.ATTRIBUTE_09;',
'    -- ABSOLUTE, RELATIVE',
'    C_BAR_WIDTH_CALCULATION CONSTANT VARCHAR2(8) := P_REGION.ATTRIBUTE_16;',
'    C_DISPLAY CONSTANT VARCHAR2(19) := P_REGION.ATTRIBUTE_11;',
'    C_PREFIX_FOR_VALUE CONSTANT VARCHAR2(4000) := P_REGION.ATTRIBUTE_12;',
'    C_POSTFIX_FOR_VALUE CONSTANT VARCHAR2(4000) := P_REGION.ATTRIBUTE_13;',
'    C_MAXIMUM_ROWS CONSTANT NUMBER := P_REGION.ATTRIBUTE_14;',
'    C_MESSAGE_WHEN_NO_DATA_FOUND CONSTANT VARCHAR2(4000) := P_REGION.ATTRIBUTE_20;',
'    ',
'    L_COLOR_COLUMN_NUMBER PLS_INTEGER;',
'    L_LABEL_COLUMN_NUMBER PLS_INTEGER;',
'    L_VALUE_COLUMN_NUMBER PLS_INTEGER;',
'    L_INITIALS_COLUMN_NUMBER PLS_INTEGER;',
'    ',
'    L_COLUMN_VALUE_LIST APEX_PLUGIN_UTIL.T_COLUMN_VALUE_LIST2;',
'    ',
'    L_COLOR VARCHAR2(4000) := NULL;',
'    L_LABEL VARCHAR2(4000) := NULL;',
'    L_LABEL_LINK VARCHAR2(4000) := NULL;',
'    L_VALUE VARCHAR2(4000) := NULL;',
'    L_VALUE_LINK VARCHAR2(4000) := NULL;',
'    L_IMAGE_URL VARCHAR2(4000) := NULL;',
'    L_CSS_ICON_CLASS_NAME VARCHAR2(4000) := NULL;',
'    L_INITIALS VARCHAR2(4000) := NULL;',
'    L_MESSAGE_WHEN_NO_DATA_FOUND VARCHAR2(4000) := NULL;',
'',
'    L_CUSTOM_CHART_COLORS_TABLE APEX_APPLICATION_GLOBAL.VC_ARR2;',
'    L_CUSTOM_CHART_COLORS VARCHAR2(32767) := NULL;',
'BEGIN',
'    L_COLUMN_VALUE_LIST := APEX_PLUGIN_UTIL.GET_DATA2(',
'        P_SQL_STATEMENT  => P_REGION.SOURCE,',
'        P_MIN_COLUMNS    => 1,',
'        P_MAX_COLUMNS    => NULL,',
'        P_COMPONENT_NAME => P_REGION.NAME,',
'        P_MAX_ROWS => C_MAXIMUM_ROWS',
'    );',
'',
'    L_COLOR_COLUMN_NUMBER := APEX_PLUGIN_UTIL.GET_COLUMN_NO (',
'        P_ATTRIBUTE_LABEL   => ''Color Column'',',
'        P_COLUMN_ALIAS      => C_COLOR_COLUMN,',
'        P_COLUMN_VALUE_LIST => L_COLUMN_VALUE_LIST,',
'        P_IS_REQUIRED       => C_COLOR_SCHEME = ''COLUMN'',',
'        P_DATA_TYPE         => APEX_PLUGIN_UTIL.C_DATA_TYPE_VARCHAR2',
'    );',
'    L_LABEL_COLUMN_NUMBER := APEX_PLUGIN_UTIL.GET_COLUMN_NO (',
'        P_ATTRIBUTE_LABEL   => ''Label Column'',',
'        P_COLUMN_ALIAS      => C_LABEL_COLUMN,',
'        P_COLUMN_VALUE_LIST => L_COLUMN_VALUE_LIST,',
'        P_IS_REQUIRED       => TRUE,',
'        P_DATA_TYPE         => APEX_PLUGIN_UTIL.C_DATA_TYPE_VARCHAR2',
'    );',
'    L_VALUE_COLUMN_NUMBER := APEX_PLUGIN_UTIL.GET_COLUMN_NO (',
'        P_ATTRIBUTE_LABEL   => ''Value Column'',',
'        P_COLUMN_ALIAS      => C_VALUE_COLUMN,',
'        P_COLUMN_VALUE_LIST => L_COLUMN_VALUE_LIST,',
'        P_IS_REQUIRED       => TRUE,',
'        P_DATA_TYPE         => APEX_PLUGIN_UTIL.C_DATA_TYPE_VARCHAR2',
'    );',
'    if C_ICON_TYPE = ''INITIALS'' then',
'        L_INITIALS_COLUMN_NUMBER := APEX_PLUGIN_UTIL.GET_COLUMN_NO (',
'            P_ATTRIBUTE_LABEL   => ''Initials Column'',',
'            P_COLUMN_ALIAS      => C_INITIALS_COLUMN,',
'            P_COLUMN_VALUE_LIST => L_COLUMN_VALUE_LIST,',
'            P_IS_REQUIRED       => true,',
'            P_DATA_TYPE         => APEX_PLUGIN_UTIL.C_DATA_TYPE_VARCHAR2',
'        );',
'    end if;',
'    -- Begin output as JSON',
'    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);',
'    HTP.P(''Cache-Control: no-cache'');',
'    HTP.P(''Pragma: no-cache'');',
'    OWA_UTIL.HTTP_HEADER_CLOSE;',
'    ',
'    IF C_COLOR_SCHEME = ''CUSTOM'' THEN',
'        L_CUSTOM_CHART_COLORS_TABLE := APEX_UTIL.STRING_TO_TABLE(CASE WHEN C_CUSTOM_CHART_COLORS IS NOT NULL THEN TRIM(BOTH '''''''' FROM APEX_ESCAPE.JS_LITERAL(C_CUSTOM_CHART_COLORS)) END, '':'');',
'        L_CUSTOM_CHART_COLORS := ''"color_scheme":['';',
'        FOR I IN L_CUSTOM_CHART_COLORS_TABLE.FIRST .. L_CUSTOM_CHART_COLORS_TABLE.LAST LOOP',
'            IF I > 1 THEN',
'                L_CUSTOM_CHART_COLORS := L_CUSTOM_CHART_COLORS||'','';',
'            END IF;',
'            L_CUSTOM_CHART_COLORS := L_CUSTOM_CHART_COLORS||''"''||L_CUSTOM_CHART_COLORS_TABLE(I)||''"'';',
'        END LOOP;',
'        L_CUSTOM_CHART_COLORS := L_CUSTOM_CHART_COLORS||''],'';',
'    END IF;',
'',
'    L_MESSAGE_WHEN_NO_DATA_FOUND := APEX_ESCAPE.HTML_WHITELIST(',
'        APEX_PLUGIN_UTIL.REPLACE_SUBSTITUTIONS (',
'                P_VALUE  => C_MESSAGE_WHEN_NO_DATA_FOUND,',
'                P_ESCAPE => FALSE',
'            )',
'        );',
'',
'    HTP.PRN(',
'        ''{''||',
'            APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                ''chart_type'',',
'                C_CHART_TYPE,',
'                FALSE,',
'                TRUE',
'            )',
'    );',
'    HTP.PRN(',
'        APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'            ''message_when_no_data_found'',',
'            L_MESSAGE_WHEN_NO_DATA_FOUND,',
'            TRUE,',
'            TRUE',
'        )',
'    );',
'    HTP.PRN(',
'        APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'            ''chart_css_class_names'',',
'            C_CHART_CSS_CLASSES,',
'            TRUE,',
'            TRUE',
'        )',
'    );',
'    HTP.PRN(',
'        APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'            ''icon_type'',',
'            C_ICON_TYPE,',
'            TRUE,',
'            TRUE',
'        )',
'    );',
'    IF C_COLOR_SCHEME = ''CUSTOM'' THEN',
'        HTP.PRN(',
'            L_CUSTOM_CHART_COLORS',
'        );',
'    ELSE',
'        HTP.PRN(',
'            APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                ''color_scheme'',',
'                C_COLOR_SCHEME,',
'                TRUE,',
'                TRUE',
'            )',
'        );',
'    END IF;',
'    HTP.PRN(',
'            APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                ''text_position'',',
'                C_TEXT_POSITION,',
'                FALSE,',
'                TRUE',
'            )||',
'            APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                ''bar_width_calculation'',',
'                C_BAR_WIDTH_CALCULATION,',
'                FALSE,',
'                TRUE',
'            )||',
'            APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                ''display'',',
'                C_DISPLAY,',
'                FALSE,',
'                TRUE',
'            )||',
'            CASE ',
'            	WHEN C_DISPLAY IN (''VALUE'') THEN',
'					APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'						''prefix_for_value'',',
'						C_PREFIX_FOR_VALUE,',
'						TRUE,',
'						TRUE',
'					)||',
'					APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'						''postfix_for_value'',',
'						C_POSTFIX_FOR_VALUE,',
'						TRUE,',
'						TRUE',
'					)',
'			END||',
'            ''"items":[''',
'    );',
'    ',
'    --FOR L_ROW_NUMBER IN L_COLUMN_VALUE_LIST(1).VALUE_LIST.FIRST .. L_COLUMN_VALUE_LIST(1).VALUE_LIST.LAST LOOP',
'    FOR L_ROW_NUMBER IN 1 .. L_COLUMN_VALUE_LIST(1).VALUE_LIST.COUNT LOOP',
'        BEGIN',
'            APEX_PLUGIN_UTIL.SET_COMPONENT_VALUES (',
'                P_COLUMN_VALUE_LIST => L_COLUMN_VALUE_LIST,',
'                P_ROW_NUM => L_ROW_NUMBER ',
'            );',
'            ',
'            IF L_ROW_NUMBER > 1 THEN',
'            	HTP.PRN('', '');',
'            END IF;',
'            ',
'            HTP.PRN(''{'');',
'            ',
'            L_LABEL := APEX_PLUGIN_UTIL.ESCAPE (',
'                APEX_PLUGIN_UTIL.GET_VALUE_AS_VARCHAR2 (',
'                    P_DATA_TYPE => L_COLUMN_VALUE_LIST(L_LABEL_COLUMN_NUMBER).DATA_TYPE,',
'                    P_VALUE => L_COLUMN_VALUE_LIST(L_LABEL_COLUMN_NUMBER).VALUE_LIST(L_ROW_NUMBER)',
'                ),',
'                P_REGION.ESCAPE_OUTPUT',
'            );',
'            HTP.PRN(',
'            	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                    ''label'',',
'                    L_LABEL,',
'                    FALSE',
'            	)',
'            );',
'            L_LABEL_LINK := ',
'                CASE ',
'                    WHEN C_LABEL_LINK IS NOT NULL THEN ',
'                        APEX_UTIL.PREPARE_URL (',
'                            APEX_PLUGIN_UTIL.REPLACE_SUBSTITUTIONS (',
'                                P_VALUE  => C_LABEL_LINK,',
'                                P_ESCAPE => FALSE',
'                            )',
'                        )',
'                END;',
'            HTP.PRN(',
'            	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                    ''label_link'',',
'                    L_LABEL_LINK',
'                )',
'            );',
'            L_VALUE := APEX_PLUGIN_UTIL.ESCAPE (',
'               APEX_PLUGIN_UTIL.GET_VALUE_AS_VARCHAR2 (',
'                   P_DATA_TYPE => L_COLUMN_VALUE_LIST(L_VALUE_COLUMN_NUMBER).DATA_TYPE,',
'                   P_VALUE => L_COLUMN_VALUE_LIST(L_VALUE_COLUMN_NUMBER).VALUE_LIST(L_ROW_NUMBER)',
'               ),',
'               P_REGION.ESCAPE_OUTPUT',
'            );',
'            HTP.PRN(',
'            	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                    ''value'',',
'                    L_VALUE,',
'                    FALSE,',
'                    C_VALUE_LINK IS NOT NULL OR L_COLOR_COLUMN_NUMBER IS NOT NULL OR C_CHART_TYPE = ''ICON''',
'                )',
'            );',
'            L_VALUE_LINK := ',
'                CASE ',
'                    WHEN C_VALUE_LINK IS NOT NULL THEN ',
'                        APEX_UTIL.PREPARE_URL (',
'                            APEX_PLUGIN_UTIL.REPLACE_SUBSTITUTIONS (',
'                                P_VALUE  => C_VALUE_LINK,',
'                                P_ESCAPE => FALSE',
'                            )',
'                        )',
'                END;',
'             HTP.PRN(',
'            	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                    ''value_link'',',
'                    L_VALUE_LINK,',
'                    TRUE,',
'                    L_COLOR_COLUMN_NUMBER IS NOT NULL OR C_CHART_TYPE = ''ICON''',
'                )',
'            );',
'            IF L_COLOR_COLUMN_NUMBER IS NOT NULL THEN',
'                L_COLOR := APEX_PLUGIN_UTIL.ESCAPE (',
'                   APEX_PLUGIN_UTIL.GET_VALUE_AS_VARCHAR2 (',
'                       P_DATA_TYPE => L_COLUMN_VALUE_LIST(L_COLOR_COLUMN_NUMBER).DATA_TYPE,',
'                       P_VALUE => L_COLUMN_VALUE_LIST(L_COLOR_COLUMN_NUMBER).VALUE_LIST(L_ROW_NUMBER)',
'                   ),',
'                   P_REGION.ESCAPE_OUTPUT',
'                );',
'                HTP.PRN(',
'                    APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                        ''color'',',
'                        L_COLOR,',
'                        FALSE,',
'                        C_CHART_TYPE = ''ICON''',
'                    )',
'                );',
'            END IF;',
'            IF C_ICON_TYPE = ''IMAGE'' THEN',
'				L_IMAGE_URL := ',
'                    CASE ',
'                        WHEN C_IMAGE_URL IS NOT NULL THEN ',
'                            APEX_UTIL.PREPARE_URL (',
'                                APEX_PLUGIN_UTIL.REPLACE_SUBSTITUTIONS (',
'                                    P_VALUE  => C_IMAGE_URL,',
'                                    P_ESCAPE => FALSE',
'                                )',
'                            )',
'                    END;',
'				HTP.PRN(',
'					APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'						''image_url'',',
'						L_IMAGE_URL,',
'						FALSE,',
'						FALSE',
'					)',
'				);',
'			ELSIF C_ICON_TYPE = ''ICON'' THEN',
'				L_CSS_ICON_CLASS_NAME := APEX_PLUGIN_UTIL.REPLACE_SUBSTITUTIONS (',
'                    P_VALUE  => C_CSS_ICON_CLASS_NAME,',
'                    P_ESCAPE => TRUE',
'                );',
'				HTP.PRN(',
'                	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'						''icon_css_class_name'',',
'						L_CSS_ICON_CLASS_NAME,',
'						FALSE,',
'						FALSE',
'					)',
'				);',
'			ELSIF C_ICON_TYPE = ''INITIALS'' THEN',
'				L_INITIALS := APEX_PLUGIN_UTIL.ESCAPE (',
'					APEX_PLUGIN_UTIL.GET_VALUE_AS_VARCHAR2 (',
'						P_DATA_TYPE => L_COLUMN_VALUE_LIST(L_INITIALS_COLUMN_NUMBER).DATA_TYPE,',
'						P_VALUE => L_COLUMN_VALUE_LIST(L_INITIALS_COLUMN_NUMBER).VALUE_LIST(L_ROW_NUMBER)',
'					),',
'					P_REGION.ESCAPE_OUTPUT',
'				);',
'				HTP.PRN(',
'                	APEX_JAVASCRIPT.ADD_ATTRIBUTE (',
'                    	''initials'',',
'	                    L_INITIALS,',
'	                    FALSE,',
'	                    FALSE',
'    	            )',
'    	        );',
'            END IF;',
'            ',
'			HTP.PRN(''}'');',
'            ',
'            APEX_PLUGIN_UTIL.CLEAR_COMPONENT_VALUES;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                APEX_PLUGIN_UTIL.CLEAR_COMPONENT_VALUES;',
'                RAISE;',
'        END;',
'    END LOOP;',
'    HTP.PRN(',
'            '']''||',
'        ''}''',
'    );',
'    ',
'    RETURN NULL;',
'END AJAX;'))
,p_api_version=>1
,p_render_function=>'RENDER'
,p_ajax_function=>'AJAX'
,p_standard_attributes=>'SOURCE_SQL:AJAX_ITEMS_TO_SUBMIT:ESCAPE_OUTPUT'
,p_substitute_attributes=>false
,p_subscribe_plugin_settings=>true
,p_help_text=>'<p>This plugin draws horizontal bar charts containing labels, values and even icons</p>'
,p_version_identifier=>'5.0.1'
,p_about_url=>'http://apex.oracle.com/plugins'
,p_files_version=>16
);
