'    where instr(:P8_INCLUDE,''C'') > 0 and',
'        ( :P8_PROJECT is null or s.id = :P8_PROJECT ) and',
'        instr(lower(PROJECT_CUSTOMER),lower(:P8_SEARCH)) > 0',
'    union all',
