'                from apex_application_build_options',
'                where application_id = :APP_ID',
'                    and build_option_name = ''Project Updates''',
'                    and build_option_status = ''Include''',
'             ) and',
'        (',
'            instr(lower(dbms_lob.substr(STATUS_UPDATE,2000,1)),lower(:P8_SEARCH)) > 0',
