'sum(decode(to_char(time_stamp,''HH24''),1,1,0)) h01,',
'sum(decode(to_char(time_stamp,''HH24''),2,1,0)) h02,',
'sum(decode(to_char(time_stamp,''HH24''),3,1,0)) h03,',
'sum(decode(to_char(time_stamp,''HH24''),4,1,0)) h04,',
