'from eba_proj_status_ms m',
'where m.milestone_status = ''Open''',
'    and m.project_id = :P107_PROJECT_ID',
'    and m.id != :P107_ID',
'order by milestone_date'))
,p_plug_source_type=>'PLUGIN_COM.ORACLE.APEX.TIMELINESTATUSLIST'
