'    l_ret_col  varchar2(30);',
'    l_error    varchar2(4000);',
'begin',
'    if eba_proj_flex_fw.validate_lov_query( :P142_LOV_SQL_QUERY,',
'                l_disp_col, l_ret_col, l_error ) then',
'        :P142_LOV_DISPLAY_COL := l_disp_col;',
