,p_process_name=>'Process Row of EBA_PROJ_FLEX_REGISTRY'
,p_attribute_02=>'EBA_PROJ_FLEX_REGISTRY'
,p_attribute_03=>'P142_ID'
,p_attribute_04=>'ID'
