'        for c1 in ( select id',
'                    from eba_proj_template_ms',
'                    where template_id = :P181_TEMPLATE_ID',
'                    start with id = :P181_PARENT_MILESTONE_ID',
'                    connect by prior parent_milestone_id = id ) loop',
'            if c1.id = :P181_ID then',
'                return false;',
