,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.id,',
'    a.name,',
'    a.description,',
'    nvl(a.inc_in_status_eml_yn,''N'') as inc_in_status_eml_yn,',
'    a.due_date_offset,',
