begin
wwv_flow_api.create_page(
 p_id=>197
,p_user_interface_id=>wwv_flow_api.id(5649249168580454179)
,p_name=>'Email Project Details Send Job'
,p_page_mode=>'MODAL'
,p_step_title=>'Email Project Details Send Job'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_step_sub_title=>'Email Project Summaries Send Job'
,p_step_sub_title_type=>'TEXT_WITH_SUBSTITUTIONS'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_api.id(5821915746499073701)
,p_page_template_options=>'#DEFAULT#:t-Dialog--noPadding'
,p_required_role=>wwv_flow_api.id(7171837742744470471)
,p_required_patch=>wwv_flow_api.id(15739050871163200134)
,p_help_text=>'<p>This job sends a "Project Details" email every <a href="f?p=&APP_ID.:57:&APP_SESSION.:">workday</a> to application users who have opted to receive these emails. Based on the user''s email preferences, this job can send "Project Details" emails for '
||'all accessible open projects, open accessible projects that the user is following, open accessible projects that the user is a member of, or open accessible projects that the user is following AND is a member of. This job respects the user''s "Project'
||' Details Schedule" email preference, meaning that just because this job runs daily, end-users will only be sent emails based on the schedule that they''ve defined in their "Project Details Schedule" email preference (Quarterly, Monthly, Bi-Monthly, We'
||'ekly or Daily). This job can be enabled or disabled, click status to change status.</p>'
,p_last_upd_yyyymmddhh24miss=>'20180223140942'
);
wwv_flow_api.create_report_region(
