'   and (',
'           instr(u.username,''@'') > 0',
'           or',
'           (',
'               instr(u.username,''@'') = 0',
'               and',
'               u.email_address is not null',
'           )',
'        )'))
,p_button_condition_type=>'EXISTS'
,p_icon_css_classes=>'fa-envelope-o'
,p_grid_new_grid=>false
);
