prompt --application/deployment/install/install_regions_and_countries
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(18844998396735937551)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Regions and Countries'
,p_sequence=>80
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create table eba_proj_regions (',
'    id                  number not null,',
'    region_name      varchar2(255),',
'    --',
'    row_version_number  number not null,',
'    created             timestamp with local time zone not null,',
'    created_by          varchar2(255) not null,',
'    updated             timestamp with local time zone,',
'    updated_by          varchar2(255),',
'    --',
'    constraint eba_proj_regions_pk primary key (id)',
')',
'/',
'create unique index eba_proj_regions_uk on eba_proj_regions(region_name)',
'/',
'alter table eba_proj_regions',
'    add constraint eba_proj_regions_uk',
'        unique (region_name)',
'        using index eba_proj_regions_uk',
'/',
'create or replace trigger biu_eba_proj_regions',
'    before insert or update on eba_proj_regions',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'        :new.row_version_number := 1;',
'    elsif updating then',
'        :new.row_version_number := nvl(:old.row_version_number,1) + 1;',
'    end if;',
'    :new.updated := localtimestamp;',
'    :new.updated_by := nvl(wwv_flow.g_user,user);',
'end biu_eba_proj_regions;',
'/',
'alter trigger biu_eba_proj_regions enable;',
'/',
'',
'create table eba_proj_countries (',
'    id                  number primary key,',
'    country_code        varchar2(30)  not null,',
'    country_name        varchar2(255) not null,',
'    region_id           number,',
'    display_yn          varchar2(1)',
'                            constraint eba_proj_countries_disp_cc',
'                            check (display_yn in (''Y'',''N'')),',
'    --',
'    row_version_number  number,',
'    created             timestamp with local time zone,',
'    created_by          varchar2(255),',
'    updated             timestamp with local time zone,',
'    updated_by          varchar2(255),',
'    --',
'    constraint eba_proj_countries_region_fk',
'        foreign key (region_id)',
'        references eba_proj_regions (id) on delete cascade',
');',
'create unique index eba_proj_countries_i1 on eba_proj_countries(country_code);',
'create unique index eba_proj_countries_i2 on eba_proj_countries(country_name);',
'create index        eba_proj_countries_i3 on eba_proj_countries(region_id);',
'',
'create or replace trigger biu_eba_proj_countries',
'    before insert or update on eba_proj_countries',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'       :new.row_version_number := 1;',
'    elsif updating then',
'        :new.row_version_number := nvl(:old.row_version_number,1) + 1;',
'    end if;',
'    :new.updated := localtimestamp;',
'    :new.updated_by := nvl(wwv_flow.g_user,user);',
'    --',
'    if :new.display_yn is null then ',
'        :new.display_yn := ''Y'';',
'    end if;',
'end;',
'/',
'alter trigger biu_eba_proj_countries enable;',
'/',
'',
'-- Load Initial Data',
'insert into eba_proj_regions (id, region_name) values (10, ''North America'');',
'insert into eba_proj_regions (id, region_name) values (20, ''South America'');',
'insert into eba_proj_regions (id, region_name) values (30, ''EMEA'');',
'insert into eba_proj_regions (id, region_name) values (40, ''Japan'');',
'insert into eba_proj_regions (id, region_name) values (50, ''Asia Pacific'');',
