prompt --application/deployment/install/install_eba_proj_status_country_ref
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(18848386092085494643)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_status_country_ref'
,p_sequence=>240
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create table eba_proj_status_country_ref$ (',
'    id          number,',
'    project_id  number not null,',
'    country_id  number not null,',
'    --',
'    created             timestamp with local time zone,',
'    created_by          varchar2(255),',
'    updated             timestamp with local time zone,',
'    updated_by          varchar2(255),',
'    --',
'    constraint eba_proj_status_country_ref_pk',
'        primary key (id),',
'    constraint eba_proj_status_country_fk1',
'        foreign key (project_id)',
'        references eba_proj_status$( id ) on delete cascade,',
'    constraint eba_proj_status_country_fk2',
'        foreign key (country_id)',
'        references eba_proj_countries( id ) on delete cascade',
');',
'create index eba_proj_status_country_ref_i1 on eba_proj_status_country_ref$( project_id );',
'create index eba_proj_status_country_ref_i2 on eba_proj_status_country_ref$( country_id );',
'',
'create or replace trigger biu_eba_proj_status_cntry_ref',
'    before insert or update on eba_proj_status_country_ref$',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if :new.project_id is not null then',
'        update eba_proj_status$ set updated = localtimestamp where id = :new.project_id;',
'    end if;',
'    :new.updated := localtimestamp;',
'    :new.updated_by := nvl(wwv_flow.g_user,user);',
'end biu_eba_proj_status_cntry_ref;',
'/',
'alter trigger biu_eba_proj_status_cntry_ref enable;',
'/',
'',
'create or replace view eba_proj_status_country_ref as',
'select rf.id,',
'    rf.project_id,',
'    rf.country_id,',
'    rf.created,',
'    rf.created_by,',
'    rf.updated,',
'    rf.updated_by',
'from eba_proj_status_country_ref$ rf',
'where exists ( select null from eba_proj_status p where p.id = rf.project_id );',
'/'))
);
end;
/
prompt --application/deployment/install/upgrade_timezone_support
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(5937933864319654950)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Timezone Support'
,p_sequence=>250
,p_script_type=>'UPGRADE'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select table_name',
'from user_tables',
'where table_name = ''EBA_PROJ_TZ_PREF'''))
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create table eba_proj_tz_pref (',
'    id                       number        not null',
'                             constraint eba_proj_tz_pref_pk',
'                             primary key,',
'    username                 varchar2(255) not null',
'                             constraint eba_proj_tz_pref_uk',
'                             unique,',
'    timezone_preference      varchar2(255) not null,',
'    --',
'    row_version_number       number                          not null,',
'    created                  timestamp with local time zone  not null,',
'    created_by               varchar2(255)                   not null,',
'    updated                  timestamp with local time zone  not null,',
'    updated_by               varchar2(255)                   not null )',
'/',
'  ',
'create or replace trigger eba_proj_tz_pref_biu',
'    before insert or update on eba_proj_tz_pref',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created    := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'        :new.row_version_number := 1;',
'    elsif updating then',
'        :new.row_version_number := nvl(:old.row_version_number,1) + 1;',
'    end if;',
'    if :new.timezone_preference is null then',
'        :new.timezone_preference := ''UTC'';',
'    end if;',
'    :new.updated    := localtimestamp;',
'    :new.updated_by := nvl(wwv_flow.g_user,user);',
'    :new.username   := upper(:new.username);',
'end;',
'/',
'',
'alter trigger eba_proj_tz_pref_biu enable;'))
);
end;
/
