prompt --application/deployment/install/install_issues
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(7538212916141267776)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'issues'
,p_sequence=>370
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Create the new issue level look-up table',
'create table eba_proj_issue_levels (',
'    id                     number primary key,',
'    name                   varchar2(255) unique not null,',
'    description            varchar2(4000),',
'    is_active_yn           varchar2(1),',
'    --',
'    created                timestamp(6) with local time zone,',
'    created_by             varchar2(255),',
'    updated                timestamp(6) with local time zone,',
'    updated_by             varchar2(255)',
')',
'/',
'',
'-- Create the new issue level biu trigger',
'create or replace trigger biu_eba_proj_issue_levels',
'    before insert or update on eba_proj_issue_levels',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if inserting or updating then',
'        :new.updated := localtimestamp;',
'        :new.updated_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'end;',
'/',
'',
'-- Enable the new issue category biu trigger',
'alter trigger biu_eba_proj_issue_levels enable',
'/',
'',
'-- Populate the issue category new look-up table',
'begin',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (1,''Critical'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (2,''Elevated'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (3,''Important'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (4,''Tracking'','''',''Y'');',
'end;',
'/',
'',
'-- Create the new issue category look-up table',
'create table eba_proj_issue_cats (',
'    id                     number primary key,',
'    name                   varchar2(255) unique not null,',
'    description            varchar2(4000),',
'    is_active_yn           varchar2(1),',
'    --',
'    created                timestamp(6) with local time zone,',
'    created_by             varchar2(255),',
'    updated                timestamp(6) with local time zone,',
'    updated_by             varchar2(255)',
')',
'/',
'',
'-- Create the new issue category biu trigger',
'create or replace trigger biu_eba_proj_issue_cats',
'    before insert or update on eba_proj_issue_cats',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if inserting or updating then',
'        :new.updated := localtimestamp;',
'        :new.updated_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'end;',
'/',
'',
'-- Enable the new issue category biu trigger',
'alter trigger biu_eba_proj_issue_cats enable',
'/',
'',
'-- Populate the new look-up table',
'begin',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (1,''Bug'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (2,''Development'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (3,''Enhancement Request'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (4,''Operations'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (5,''Regression'','''',''Y'');',
'end;',
'/',
'',
'create table eba_proj_status_issues$ (',
'    id                      number',
'                            constraint eba_proj_status_issues_pk',
'                            primary key,',
'    row_version_number      number,',
'    row_key                 varchar2(30),',
'    resolution              varchar2(4000),',
'    project_id              number',
'                            constraint eba_proj_status_issues_fk',
'                            references eba_proj_status$(id)',
'                            on delete cascade,',
'    cat_id                  constraint eba_proj_issues_cat_fk',
'                            references eba_proj_issue_cats(id)',
'                            on delete set null,',
'    issue                   varchar2(255) not null,',
'    tags                    varchar2(4000),',
'    ref_num                 varchar2(255),',
'    issue_detail            clob,',
'    owner_role_id           number',
'                            constraint eba_proj_issue_owner_fk',
'                            references eba_proj_roles( id )',
