prompt --application/deployment/install/install_create_tag_tables
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(6035008059843725894)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'create tag tables'
,p_sequence=>380
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'CREATE TABLE eba_proj_tags$ (',
'    id                      number primary key,',
'    row_version_number      number,',
'    tag                     varchar2(255) not null,',
'    content_id              number,',
'    content_type            varchar2(30)',
'                            constraint eba_proj_tags_ck check',
'                            (content_type in (''STATUS'',''STATUS_ISSUES'',''FILE'',''AI'',''MILESTONE'',''LINK'',''UPDATES'')),',
'    --',
'    created                 timestamp with local time zone,',
'    created_by              varchar2(255),',
'    updated                 timestamp with local time zone,',
'    updated_by              varchar2(255)',
'    )',
'/',
'',
'create unique index eba_proj_tags_i1 on eba_proj_tags$(tag, content_id);',
'create unique index eba_proj_tags_i2 on eba_proj_tags$(content_id, tag);',
'',
'create or replace view eba_proj_tags as',
'select id, ',
'    row_version_number, ',
'    tag, ',
'    content_id, ',
'    content_type, ',
'    created, ',
'    created_by, ',
'    updated, ',
'    updated_by ',
'from eba_proj_tags$ t',
'where ( t.content_type = ''AI''',
'        and exists ( select null from eba_proj_status_ais a where t.content_id = a.id ))',
'    or ( t.content_type = ''MILESTONE''',
'        and exists ( select null from eba_proj_status_ms m where t.content_id = m.id ))',
'    or ( t.content_type = ''FILE''',
'        and exists ( select null from eba_proj_status_files f where t.content_id = f.id ))',
'    or ( t.content_type = ''STATUS''',
'        and exists ( select null from eba_proj_status p where t.content_id = p.id ))',
'    or ( t.content_type = ''STATUS_ISSUES''',
'        and exists ( select null from eba_proj_status_issues p where t.content_id = p.id ))',
'    or ( t.content_type = ''LINK''',
'        and exists ( select null from eba_proj_status_links l where t.content_id = l.id ))',
'    or ( t.content_type = ''UPDATES''',
'        and exists ( select null from eba_proj_status_updates u where t.content_id = u.id ))',
'/',
'',
'create or replace view eba_proj_tags_type_sum as',
'select tag, ',
'    content_type, ',
'    count(*) tag_count ',
'from eba_proj_tags',
'group by tag, content_type',
'/',
'',
'create or replace view eba_proj_tags_sum as',
'select tag, ',
'    count(*) tag_count ',
'from eba_proj_tags',
'group by tag',
'/'))
);
end;
/
prompt --application/deployment/install/upgrade_update_status_colors
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(7311018612618796210)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Update Status Colors'
,p_sequence=>390
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_image_prefix  varchar2(255);',
'begin',
'    l_image_prefix := v(''IMAGE_PREFIX'');',
'',
'    -- In case this old color is still around.',
'    update eba_proj_color_codes set color_name = ''GRAY'' where upper(color_name) = ''DARK GRAY'';',
'',
'    merge into eba_proj_color_codes dest using (',
'        select ''BLACK'' color_name,',
'            ''#303030'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''BLUE'' color_name,',
'            ''#4183D7'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''BLUESKY'' color_name,',
'            ''#6BB9F0'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''BROWN'' color_name,',
'            ''#D88935'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''CYAN'' color_name,',
'            ''#1ABC9C'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''DARKBLUE'' color_name,',
'            ''#1F5F97'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''GRAY'' color_name,',
'            ''#A0A0A0'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''GREEN'' color_name,',
'            ''#2ECC71'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -80 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''LIME'' color_name,',
'            ''#28A346'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''ORANGE'' color_name,',
'            ''#F39C12'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -120 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''RED'' color_name,',
'            ''#D91E18'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            0 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''SILVER'' color_name,',
'            ''#BDC3C7'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -160 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual',
'        union all',
'        select ''YELLOW'' color_name,',
'            ''#F1C40F'' color_code,',
'            l_image_prefix||''eba/img/status_indicator.png'' sprite_url,',
'            0 sprite_position_x,',
'            -40 sprite_position_y,',
'            1 display_sequence,',
'            ''Y'' is_active_yn',
'        from dual ) src',
'    on ( dest.color_name = src.color_name )',
'    when not matched then',
'        insert (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn)',
'        values (src.color_name, src.color_code, src.sprite_url, src.sprite_position_x, src.sprite_position_y, src.display_sequence, src.is_active_yn)',
'    when matched then',
'        update set color_code = src.color_code;',
'',
'end;'))
);
end;
