prompt --application/deployment/install/upgrade_past_due_email_send_job
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(11958283033444688913)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Past Due Email Send Job'
,p_sequence=>440
,p_script_type=>'UPGRADE'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>'select null from user_scheduler_jobs where job_name = ''EBA_PROJ_EMAIL_PAST_DUE_JOB'';'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_schema          varchar2(30);',
'    l_program         varchar2(30)                   := ''EBA_PROJ_EMAIL_PAST_DUE_PRG'';',
'    l_job             varchar2(30)                   := ''EBA_PROJ_EMAIL_PAST_DUE_JOB'';',
'    l_action          varchar2(50)                   := ''eba_proj_stat_email.send_past_due_emails'';',
'    l_freq            varchar2(255)                  := ''freq=daily; byhour=8; byminute=0; bysecond=0;'';',
'    l_num_params      number                         := 1;',
'    l_prog_type       varchar2(20)                   := ''STORED_PROCEDURE'';',
'    l_param_name      varchar2(10)                   := ''P_APP_ID'';',
'    l_param_type      varchar2(10)                   := ''NUMBER'';',
'    l_start_ts        timestamp with local time zone := systimestamp;',
'    l_job_comments    varchar2(255)                  := ''Sends past due milestones and action items emails.'';',
'    l_scheduler       varchar2(10)                   := ''dbms'';',
'    l_sql_stmt        varchar2(3000);',
'begin',
'    for c1 in ( select null',
'                from all_objects',
'                where object_type = ''PACKAGE''',
'                    and object_name = ''CLOUD_SCHEDULER'' ) loop',
'        l_scheduler := ''cloud'';',
'    end loop;',
'',
'    -- Create program and job',
'    begin',
'        l_sql_stmt := ''begin ''||l_scheduler||''_scheduler.create_program (',
'            program_name        => :1,',
'            program_type        => :2,',
'            program_action      => :3,',
'            number_of_arguments => :4,',
'            enabled             => false); end;'';',
'',
'        execute immediate l_sql_stmt using l_program, l_prog_type, l_action, l_num_params;',
'',
'        l_sql_stmt := ''begin ''||l_scheduler||''_scheduler.define_program_argument (',
'            program_name      => :1,',
'            argument_position => :2,',
'            argument_name     => :3,',
'            argument_type     => :4 ); end;'';',
'',
'        execute immediate l_sql_stmt using l_program, l_num_params, l_param_name, l_param_type;',
'',
'    exception when others then',
'        -- ORA-00955: name is already used by an existing object',
'        if sqlcode not in (-955,-27477) then',
'            raise;',
'        end if;',
'    end;',
'',
'    begin',
'        l_sql_stmt := ''begin ''||l_scheduler||''_scheduler.create_job (',
'            job_name        => :1,',
'            program_name    => :2,',
'            start_date      => :3,',
'            repeat_interval => :4,',
'            -- The job is created disabled by default. Enable only in those environments where this is actually needed.',
'            enabled         => false,',
'            comments        => :5 ); end;'';',
'',
'        execute immediate l_sql_stmt using l_job, l_program, l_start_ts, l_freq, l_job_comments;',
'',
'    exception when others then',
'        -- ORA-00955: name is already used by an existing object',
'        if sqlcode not in (-955,-27477) then',
'            raise;',
'        end if;',
'    end;',
'',
'end;',
'/'))
);
end;
/
prompt --application/deployment/install/install_timezone_table
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(5937933551852651309)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Timezone Table'
,p_sequence=>440
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create table eba_proj_tz_pref (',
'    id                       number        not null',
'                             constraint eba_proj_tz_pref_pk',
'                             primary key,',
'    username                 varchar2(255) not null',
'                             constraint eba_proj_tz_pref_uk',
'                             unique,',
'    timezone_preference      varchar2(255) not null,',
'    --',
'    row_version_number       number                          not null,',
'    created                  timestamp with local time zone  not null,',
'    created_by               varchar2(255)                   not null,',
'    updated                  timestamp with local time zone  not null,',
'    updated_by               varchar2(255)                   not null )',
'/',
'  ',
'create or replace trigger eba_proj_tz_pref_biu',
'    before insert or update on eba_proj_tz_pref',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created    := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'        :new.row_version_number := 1;',
'    elsif updating then',
'        :new.row_version_number := nvl(:old.row_version_number,1) + 1;',
'    end if;',
'    if :new.timezone_preference is null then',
'        :new.timezone_preference := ''UTC'';',
'    end if;',
'    :new.updated    := localtimestamp;',
'    :new.updated_by := nvl(wwv_flow.g_user,user);',
'    :new.username   := upper(:new.username);',
'end;',
'/',
'    ',
'alter trigger eba_proj_tz_pref_biu enable;'))
);
end;
/
prompt --application/deployment/install/install_ms_ai_number_mviews
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(1980678958290329150)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'MS/AI Number MViews'
,p_sequence=>450
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create table eba_proj_status_ms_no_tbl as',
'select ms.project_id,',
'    ms.id milestone_id,',
'    rank() over (partition by ms.project_id',
'                 order by ms.milestone_start_date, lower(ms.milestone_name)) by_start_date,',
'    rank() over (partition by ms.project_id',
'                 order by ms.milestone_date, lower(ms.milestone_name)) by_end_date',
'from eba_proj_status_ms$ ms;',
'',
'create unique index eba_proj_status_ms_no_tbl_idx on',
'    eba_proj_status_ms_no_tbl ( project_id, milestone_id );',
'',
'create or replace view eba_proj_status_ms_no_v as ',
'  select mn.project_id,',
'    mn.milestone_id,',
'    case when ( select nvl(preference_value,''END'')',
'                from eba_proj_preferences',
'                where preference_name = ''MILESTONE_SORT_ORDER'') = ''START'' then',
'            mn.by_start_date',
'        else',
'            mn.by_end_date',
'    end as milestone_number',
'from eba_proj_status_ms_no_tbl mn;',
'',
'create table eba_proj_status_ai_no_tbl as ',
'  select ai.project_id,',
'    ai.milestone_id,',
'    ai.id action_item_id,',
'    rank() over (partition by ai.project_id, ai.milestone_id order by nvl(ai.completed_date,ai.due_date), lower(ai.action)) action_item_number',
'from eba_proj_status_ais$ ai;',
'',
'create unique index eba_proj_status_ai_no_tbl_idx on',
'    eba_proj_status_ai_no_tbl ( project_id, milestone_id, action_item_id );',
'    ',
'create or replace trigger aiud_eba_proj_status_ms_no',
'    after insert or update or delete on eba_proj_status_ms$',
'--    for each row -- Note: this trigger is a STATEMENT trigger, rather than a ROW trigger.',
'begin',
'    delete from  eba_proj_status_ms_no_tbl;',
'',
'    insert into eba_proj_status_ms_no_tbl ( project_id, milestone_id, by_start_date, by_end_date )',
'    select ms.project_id,',
'        ms.id milestone_id,',
'        rank() over (partition by ms.project_id',
'                     order by ms.milestone_start_date, lower(ms.milestone_name)) by_start_date,',
'        rank() over (partition by ms.project_id',
'                     order by ms.milestone_date, lower(ms.milestone_name)) by_end_date',
'    from eba_proj_status_ms$ ms',
'    where ms.is_deleted_yn = ''N'';',
'end;',
'/',
'',
'create or replace trigger aiud_eba_proj_status_ai_no',
'    after insert or update or delete on eba_proj_status_ais$',
'--    for each row -- Note: this trigger is a STATEMENT trigger, rather than a ROW trigger.',
'begin',
'    delete from  eba_proj_status_ai_no_tbl;',
'',
'    insert into eba_proj_status_ai_no_tbl ( project_id, milestone_id, action_item_id, action_item_number )',
'    select ai.project_id,',
'        ai.milestone_id,',
'        ai.id action_item_id,',
'        rank() over (partition by ai.project_id, ai.milestone_id',
'                     order by nvl(ai.completed_date,ai.due_date), lower(ai.action)) action_item_number',
'    from eba_proj_status_ais$ ai',
'    where ai.is_deleted_yn = ''N'';',
'end;',
'/'))
);
end;
/
