prompt --application/deployment/install/upgrade_add_owner_role_id_to_action_items
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(15204139921177471942)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Add owner_role_id to Action Items'
,p_sequence=>540
,p_script_type=>'UPGRADE'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null',
'from user_tab_cols',
'where table_name = ''EBA_PROJ_STATUS_AIS$''',
'    and column_name = ''OWNER_ROLE_ID'''))
,p_script_clob=>'alter table EBA_PROJ_STATUS_AIS$ add owner_role_id number;'
);
end;
