'        :new.display_yn := ''Y'';',
'    end if;',
'end biu_eba_proj_countries;',
'/',
'alter trigger biu_eba_proj_countries enable;',
'/',
'',
'create table eba_proj_status_country_ref$ (',
'    id          number,',
'    project_id  number not null,',
'    country_id  number not null,',
