'',
'',
'create or replace trigger bd_proj_status',
'    before delete on eba_proj_status$',
'    for each row',
'begin',
'    eba_proj_fw.tag_sync(',
'        p_new_tags      => null,',
'        p_old_tags      => :old.tags,',
'        p_content_type  => ''STATUS'',',
'        p_content_id    => :old.id );',
'end;',
'/',
'',
'',
'create or replace trigger bi_eba_proj_status',
'    before insert or update on eba_proj_status$',
'    for each row',
'begin',
'    if :new.tags is not null then',
'        :new.tags := eba_proj_fw.tags_cleaner(:new.tags);',
'    end if;',
'    if (inserting or updating) and nvl(dbms_lob.getlength(:new.logo_blob),0) > 51200 then',
'        raise_application_error(-20000, ''The size of the uploaded file was over 50KB. Please upload a smaller file.'');',
'    end if;',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'        :new.row_version_number := 1;',
'    elsif updating then',
'        :new.row_version_number := nvl(:old.row_version_number,1) + 1;',
'    end if;',
'    if inserting or updating then',
'        :new.updated := localtimestamp;',
'        :new.updated_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if :new.row_key is null then',
'        select eba_proj_fw.compress_int(eba_proj_seq.nextval) into :new.row_key from dual;',
'    end if;',
'    if :new.headline is null then',
'        :new.headline_last_updated := null;',
'    elsif :new.headline != nvl(:old.headline,''#X#X#X'') then',
'        :new.headline_last_updated := localtimestamp;',
'    end if;',
'    eba_proj_fw.tag_sync(',
'        p_new_tags      => :new.tags,',
'        p_old_tags      => :old.tags,',
'        p_content_type  => ''STATUS'',',
'        p_content_id    => :new.id );',
'end;',
'/'))
);
end;
/
prompt --application/deployment/install/upgrade_issue_categories_and_reference_id
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(3902200601714268388)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Issue Categories and Reference ID'
,p_sequence=>790
,p_script_type=>'UPGRADE'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null',
'  from user_tab_cols',
' where table_name = ''EBA_PROJ_STATUS_ISSUES$''',
'   and column_name = ''CAT_ID'''))
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Create the new issue category look-up table',
'create table eba_proj_issue_cats (',
'    id                     number primary key,',
'    name                   varchar2(255) unique not null,',
'    description            varchar2(4000),',
'    is_active_yn           varchar2(1),',
'    --',
'    created                timestamp(6) with local time zone,',
'    created_by             varchar2(255),',
'    updated                timestamp(6) with local time zone,',
'    updated_by             varchar2(255)',
')',
'/',
'',
'-- Create the new issue category biu trigger',
'create or replace trigger biu_eba_proj_issue_cats',
'    before insert or update on eba_proj_issue_cats',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if inserting or updating then',
'        :new.updated := localtimestamp;',
'        :new.updated_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'end;',
'/',
'',
'-- Enable the new issue category biu trigger',
'alter trigger biu_eba_proj_issue_cats enable',
'/',
'',
'-- Populate the new look-up table (for pages 153 & 218)',
'begin',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (1,''Bug'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (2,''Development'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (3,''Enhancement Request'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (4,''Operations'','''',''Y'');',
'    insert into eba_proj_issue_cats (id, name, description, is_active_yn) values (5,''Regression'','''',''Y'');',
'end;',
'/',
'',
'-- Add the new cat_id and ref_num columns to the EBA_PROJ_STATUS_ISSUES$ table',
'alter table EBA_PROJ_STATUS_ISSUES$ add (cat_id references eba_proj_issue_cats(id) on delete set null, ref_num varchar2(255));',
'/',
'',
'-- Since these will most likely be used in where clauses - let''s index these new columns',
'create index  eba_proj_status_issues_i4 on eba_proj_status_issues$(cat_id);',
'create index  eba_proj_status_issues_i5 on eba_proj_status_issues$(ref_num);',
'',
'-- Recreate the secure view (with new cat_id and ref_num columns added)',
'create or replace view eba_proj_status_issues as',
'select id,',
'    row_version_number,',
'    row_key,',
'    resolution,',
'    project_id,',
'    cat_id,',
'    ref_num,',
'    issue,',
'    issue_detail,',
'    owner_role_id,',
'    issue_owner,',
'    issue_level,',
'    link_01,',
'    link_02,',
'    link_03,',
'    link_04,',
'    link_05,',
'    link_06,',
'    link_07,',
'    link_08,',
'    link_name_01,',
'    link_name_02,',
'    link_name_03,',
'    link_name_04,',
