'from eba_proj_status_ms$ m',
'where exists ( select null from eba_proj_status ps where ps.id = m.project_id )',
'    and is_deleted_yn = ''N'';',
'',
'create or replace view eba_proj_status_files as',
'    select id, ',
'        row_version_number, ',
