'        updated, ',
'        updated_by ',
'    from eba_proj_status_files$ f',
'    where exists ( select null from eba_proj_status ps where ps.id = f.project_id );',
'',
'create or replace view eba_proj_status_reports as',
'    select id,',
'        row_version_number,',
'        report_name,',
'        report_description,',
'        row_key,',
'        created,',
'        created_by,',
'        updated,',
'        updated_by',
'    from eba_proj_status_reports$;',
'',
'create or replace view eba_proj_status_rpt_proj_upd as',
'    select id, ',
'        row_version_number, ',
'        update_id, ',
'        report_id, ',
'        project_id, ',
'        created, ',
'        created_by, ',
'        updated, ',
'        updated_by ',
'    from eba_proj_status_rpt_proj_upd$ u',
'    where exists ( select null from eba_proj_status ps where ps.id = u.project_id );',
'',
'create or replace view eba_proj_status_ai_cmnts as',
'    select id, ',
'        row_version_number, ',
'        action_item_id, ',
'        comment_text, ',
'        created, ',
'        created_by, ',
'        updated, ',
'        updated_by ',
'    from eba_proj_status_ai_cmnts$ ac',
'    where exists (select null from eba_proj_status_ais ai where ai.id = ac.action_item_id );',
'',
'create or replace view eba_proj_history as',
'    select id,',
'        row_version_number,',
'        component_id,',
'        component_rowkey,',
'        table_name,',
'        column_name,',
'        old_value,',
'        new_value,',
'        change_date,',
'        changed_by',
'    from eba_proj_history$;',
'',
'create or replace view eba_proj_status_rpts as',
'    select id, ',
'        row_version_number, ',
'        row_key, ',
'        project_id, ',
'        status_title, ',
'        status_update, ',
'        update_date, ',
'        update_owner, ',
'        viewable_by, ',
'        editable_by, ',
'        created, ',
'        created_by, ',
'        updated, ',
'        updated_by ',
'    from eba_proj_status_rpts$ r',
'    where exists ( select null from eba_proj_status ps where ps.id = r.project_id );',
'',
'create or replace view eba_proj_resources as',
'    select id,',
'        row_version_number,',
'        project_id,',
'        resource_name,',
'        notes,',
'        resource_type_id,',
'        --',
'        created,',
'        created_by,',
'        updated,',
'        updated_by',
'    from eba_proj_resources$ r',
'    where exists ( select null',
'                   from eba_proj_status p',
'                   where p.id = r.project_id );',
'',
'create or replace view eba_proj_tags as',
'    select id, ',
'        row_version_number, ',
'        tag, ',
'        content_id, ',
'        content_type, ',
'        created, ',
'        created_by, ',
'        updated, ',
'        updated_by ',
'    from eba_proj_tags$ t',
'    where ( t.content_type = ''AI''',
'            and exists ( select null from eba_proj_status_ais a where t.content_id = a.id ))',
'        or ( t.content_type = ''MILESTONE''',
'            and exists ( select null from eba_proj_status_ms m where t.content_id = m.id ))',
'        or ( t.content_type = ''FILE''',
'            and exists ( select null from eba_proj_status_files f where t.content_id = f.id ))',
'        or ( t.content_type = ''STATUS''',
'            and exists ( select null from eba_proj_status p where t.content_id = p.id ))',
'        or ( t.content_type = ''LINK''',
'            and exists ( select null from eba_proj_status_links l where t.content_id = l.id ))',
'        or ( t.content_type = ''UPDATES''',
'            and exists ( select null from eba_proj_status_updates u where t.content_id = u.id ));',
'',
'create or replace view eba_proj_tags_type_sum as',
'    select tag, ',
'        content_type, ',
'        count(*) tag_count ',
'    from eba_proj_tags',
'    group by tag, content_type;',
'',
'create or replace view eba_proj_tags_sum as',
'    select tag, ',
'        count(*) tag_count ',
'    from eba_proj_tags',
'    group by tag;',
'',
'create or replace view eba_proj_status_issues as',
'select id,',
'    row_version_number,',
'    row_key,',
'    cat_id,',
'    ref_num,',
'    resolution,',
'    project_id,',
'    issue,',
'    issue_detail,',
'    owner_role_id,',
'    issue_owner,',
'    issue_level,',
'    link_01,',
'    link_02,',
'    link_03,',
'    link_04,',
'    link_05,',
'    link_06,',
'    link_07,',
'    link_08,',
'    link_name_01,',
'    link_name_02,',
'    link_name_03,',
'    link_name_04,',
'    link_name_05,',
'    link_name_06,',
'    link_name_07,',
'    link_name_08,',
'    is_open,',
'    resolved_on,',
'    created,',
'    created_by,',
'    updated,',
'    updated_by',
'from eba_proj_status_issues$ i',
'where exists ( select null from eba_proj_status ps where ps.id = i.project_id );',
'',
'create or replace view eba_proj_status_country_ref as',
'select rf.id,',
'    rf.project_id,',
'    rf.country_id,',
'    rf.created,',
'    rf.created_by,',
'    rf.updated,',
'    rf.updated_by',
'from eba_proj_status_country_ref$ rf',
'where exists ( select null from eba_proj_status p where p.id = rf.project_id );',
'/'))
);
end;
/
prompt --application/deployment/install/install_seed_data
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(8878075785625758989)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'seed data'
,p_sequence=>810
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package eba_proj_status_data_api as',
'    procedure load_look_up_data;',
'    procedure load_sample_data;',
'    procedure remove_sample_data;',
'end eba_proj_status_data_api;',
'/',
'show errors',
'',
'',
'create or replace package body eba_proj_status_data_api as',
'',
'    function varchar2_to_blob(p_varchar2_tab in dbms_sql.varchar2_table)',
'      return blob',
'    is',
'      l_blob blob;',
'      l_raw  raw(500);',
'      l_size number;',
'    begin',
'      dbms_lob.createtemporary(l_blob, true, dbms_lob.session);',
'      for i in 1 .. p_varchar2_tab.count loop',
'        l_size := length(p_varchar2_tab(i)) / 2;',
'        dbms_lob.writeappend(l_blob, l_size, hextoraw(p_varchar2_tab(i)));',
'      end loop;',
'      return l_blob;',
'    exception',
'      when others then',
'        dbms_lob.close(l_blob);',
'    end varchar2_to_blob;  ',
'',
'',
'    procedure load_look_up_data is',
'        l_image_prefix  varchar2(255);',
'    begin',
'        l_image_prefix := v(''IMAGE_PREFIX'');',
'',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (1, ''Prototype'', 1);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (2, ''Cloudification'', 2);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (3, ''Modernization'', 3);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (4, ''Research & Development'', 4);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (5, ''IT Operations'', 5);',
'        commit;',
'',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (1, ''RED'',''#D91E18'',l_image_prefix||''eba/img/status_indicator.png'',0,0, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (2, ''GREEN'',''#2ECC71'',l_image_prefix||''eba/img/status_indicator.png'',0,-80, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (3, ''YELLOW'',''#F1C40F'',l_image_prefix||''eba/img/status_indicator.png'',0,-40, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (4, ''BLACK'',''#303030'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (5, ''SILVER'',''#BDC3C7'',l_image_prefix||''eba/img/status_indicator.png'',0,-160, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (6, ''GRAY'',''#A0A0A0'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (7, ''ORANGE'',''#F39C12'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (8, ''LIME'',''#28A346'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (9, ''DARKBLUE'',''#1F5F97'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (10, ''BLUE'',''#4183D7'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (11, ''BLUESKY'',''#6BB9F0'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (12, ''BROWN'',''#D88935'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (id, color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (13, ''CYAN'',''#1ABC9C'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        commit;',
'',
