'        select 1,''Hot'',1,c.id,''N'',''Y'' from eba_proj_color_codes c where c.color_name = ''RED'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 2,''Elevated'',2,c.id,''N'',''Y'' from eba_proj_color_codes c where c.color_name = ''YELLOW'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 3,''On Track'',3,c.id,''N'',''Y'' from eba_proj_color_codes c where c.color_name = ''GRAY'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 4,''Complete'',4,c.id,''Y'',''Y'' from eba_proj_color_codes c where c.color_name = ''BLACK'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 5,''Dormant'',5,c.id,''N'',''Y'' from eba_proj_color_codes c where c.color_name = ''SILVER'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 6,''Unknown'',6,c.id,''N'',''Y'' from eba_proj_color_codes c where c.color_name = ''SILVER'';',
'        insert into EBA_PROJ_STATUS_CODES (ID, STATUS_SHORT_DESC, display_sequence, color_code_id, is_closed_status, is_active_yn)',
'        select 7,''Cancelled'',7,c.id,''N'',''N'' from eba_proj_color_codes c where c.color_name = ''BLACK'';',
'        commit;',
'',
'        insert into eba_proj_status_update_types (id, status_update_type, is_active_yn, display_sequence) values (1, ''General'', ''Y'', 1);',
'        insert into eba_proj_status_update_types (id, status_update_type, is_active_yn, display_sequence) values (2, ''Accomplishment'', ''Y'', 2);',
'        insert into eba_proj_status_update_types (id, status_update_type, is_active_yn, display_sequence) values (3, ''Question'', ''Y'', 3);',
'        insert into eba_proj_status_update_types (id, status_update_type, is_active_yn, display_sequence) values (4, ''Decision'', ''Y'', 4);',
'        commit;',
'',
'        insert into EBA_PROJ_PREFERENCES (id, preference_name) values (1,''EMAIL'');',
'        insert into EBA_PROJ_PREFERENCES (id, preference_name, preference_value) values (2,''USERNAME_FORMAT'', ''EMAIL'');',
'        insert into EBA_PROJ_PREFERENCES (id, preference_name, preference_value) values (3,''MOST_IMPORTANT_PROJECT_ROLE'', (select id from eba_proj_roles where name = ''Project Manager''));',
'',
'        insert into EBA_PROJ_STATUS_AIS_TYPES (id, ai_type, display_sequence, is_active_yn) values (1, ''New Feature'',1,''Y'');',
'        insert into EBA_PROJ_STATUS_AIS_TYPES (id, ai_type, display_sequence, is_active_yn) values (2, ''Enhancement Request'',2,''Y'');',
'        insert into EBA_PROJ_STATUS_AIS_TYPES (id, ai_type, display_sequence, is_active_yn) values (3, ''Bug'',3,''Y'');',
'        commit;',
'',
