'        commit;',
'',
'        insert into EBA_PROJ_PREFERENCES (id, preference_name, preference_value) values (6, ''PROJECT_SUMMARY_SCHEDULE'', ''MONTHLY'');',
'        insert into eba_proj_preferences (id, preference_name, preference_value ) values (7,  ''WORKDAYS'', ''2:3:4:5:6'' );',
