'        eba_proj_countries c',
'     where rf.created >= (trunc(sysdate) - 90)',
'        and c.id = rf.country_id',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Countries''',
'            )',
'union all',
'    select ''Status Report Added'' comment_text,',
'           f.status_title as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_rpts f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Status Reports''',
'            )',
'union all',
'    select ''Link Added'' comment_text,',
'           f.link_target as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_links f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Links''',
'            )',
'union all',
'    select ''Milestone Added'' comment_text,',
'           f.milestone_name as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_ms f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Milestones''',
'            )',
'union all',
'    select ''Milestone Removed'' comment_text,',
'           f.milestone_name as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.deleted_by) user_name,',
'           f.deleted_on comment_date,',
'           f.deleted_on,',
'           f.deleted_by as user_id,',
'           f.project_id',
'      from eba_proj_status_ms$ f',
'     where f.is_deleted_yn = ''Y''',
'        and f.deleted_on >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Milestones''',
'            )',
'union all',
'    select ''Action Item Added'' comment_text,',
'           f.action as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_ais f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Action Items''',
'            )',
'union all',
'    select ''Action Item Removed'' comment_text,',
'           f.action as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.deleted_by) user_name,',
'           f.deleted_on comment_date,',
'           f.deleted_on,',
'           f.deleted_by as user_id,',
'           f.project_id',
'      from eba_proj_status_ais$ f',
'     where f.is_deleted_yn = ''Y''',
'        and f.deleted_on >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Action Items''',
'            )',
'union all',
'    select ''Verification Added'' comment_text,',
'           substr(f.verification_comment,1,100) as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_verifications f',
'     where f.created >= (trunc(sysdate) - 90)',
'union all',
'    select ''Update Added'' comment_text,',
'           case when dbms_lob.getlength(f.status_update) > 100 then',
'               dbms_lob.substr(f.status_update, 100, 1) || ''...''',
'           else',
'               dbms_lob.substr(f.status_update, 100, 1)',
'           end as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_updates f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Updates''',
'            )',
'union all',
'    select ''Issue Added'' comment_text,',
'           f.issue as affected_item,',
'           '' '' attribute_1,',
'           '' '' attribute_2,',
'           lower(f.created_by) user_name,',
'           f.created comment_date,',
'           f.created,',
'           f.created_by as user_id,',
'           f.project_id',
'      from eba_proj_status_issues f',
'     where f.created >= (trunc(sysdate) - 90)',
'        and exists (select null',
'                    from build_options',
'                    where build_option_name = ''Project Issues''',
'            )',
'union all',
'    select replace(initcap(replace(replace(f.column_name,''_ID'',null),''_'','' '')), chr(10),''<br>'') || '' Updated'' comment_text,',
'           null as affected_item,',
'           apex_escape.html(substr(f.old_value,1,255)) attribute_1,',
'           apex_escape.html(substr(f.new_value,1,255)) attribute_2,',
'           lower(f.changed_by) user_name,',
'           f.change_date comment_date,',
'           f.change_date as created,',
'           u.username as user_id,',
'           f.component_id as project_id',
'      from eba_proj_history f,',
'           eba_proj_status_users u',
'     where upper(f.changed_by) = upper(u.username)',
'       and f.change_date >= (trunc(sysdate) - 90)',
'union all',
'    select ''Action Item '' || replace(replace(initcap(replace(replace(f.column_name,''PROJECT_ID'',null),''_'','' '')), chr(10),''<br>''), ''Action '', null) || '' Updated'' comment_text,',
'           ai.action as affected_item,',
'           decode(f.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(f.old_value,1,255))) attribute_1,',
'           decode(f.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(f.new_value,1,255))) attribute_2,',
'           lower(f.changed_by) user_name,',
'           f.change_date comment_date,',
'           f.change_date as created,',
'           u.username as user_id,',
'           ai.project_id',
'      from eba_proj_history f,',
'           eba_proj_status_ais ai,',
'           eba_proj_status_users u',
'     where upper(f.changed_by) = upper(u.username)',
'       and f.table_name = ''STATUS_AIS''',
'       and f.component_id = ai.id',
'       and f.change_date >= (trunc(sysdate) - 90)',
'       and exists (select null',
'            from build_options',
'            where build_option_name = ''Project Action Items''',
'    )',
'union all',
'    select ''Milestone '' || replace(replace(initcap(replace(replace(f.column_name,''PROJECT_ID'',null),''_'','' '')), chr(10),''<br>''), ''Milestone '', null) || '' Updated'' comment_text,',
'           ms.milestone_name as affected_item,',
'           decode(f.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(f.old_value,1,255))) attribute_1,',
'           decode(f.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(f.new_value,1,255))) attribute_2,',
'           lower(f.changed_by) user_name,',
'           f.change_date comment_date,',
'           f.change_date as created,',
'           u.username as user_id,',
'           ms.project_id',
'      from eba_proj_history f,',
'           eba_proj_status_ms ms,',
'           eba_proj_status_users u',
'     where upper(f.changed_by) = upper(u.username)',
'       and f.table_name = ''STATUS_MS''',
'       and f.component_id = ms.id',
'       and f.change_date >= (trunc(sysdate) - 90)',
'       and exists (select null',
'            from build_options',
'            where build_option_name = ''Project Milestones''',
'    )',
'union all',
'    select ''Issue '' || replace(initcap(replace(replace(h.column_name,''PROJECT_ID'',null),''_'','' '')), chr(10),''<br>'') || '' Updated'' as comment_text,',
'           i.issue as affected_item,',
'           decode(h.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(h.old_value,1,255))) attribute_1,',
'           decode(h.column_name, ''PROJECT_ID'', null, ',
'           apex_escape.html(substr(h.new_value,1,255))) attribute_2,',
'           lower(h.changed_by) user_name,',
'           h.change_date comment_date,',
'           h.change_date as created,',
'           u.username as user_id,',
'           i.project_id',
'      from eba_proj_history h,',
'           eba_proj_status_issues i,',
'           eba_proj_status_users u',
'     where upper(h.changed_by) = upper(u.username)',
'       and h.table_name = ''STATUS_ISSUES''',
'       and h.component_id = i.id',
'       and h.change_date >= (trunc(sysdate) - 90)',
'       and exists (select null',
'            from build_options',
'            where build_option_name = ''Project Issues''',
'    );'))
);
end;
/
prompt --application/deployment/install/upgrade_eba_proj_stat_get_con_comp
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(7297045570013459264)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_stat_get_con_comp'
,p_sequence=>870
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace function eba_proj_stat_get_con_comp (',
'    p_project_id in number,',
'    p_format     in varchar2 default ''HTML'')',
'    return varchar2',
'    -- valid p_format values STRING, HTML, NUMBER',
'as',
'   l_project_score number := 0;',
'   l_max_value number := 0;',
'   l_closed varchar2(1);',
'   l_active varchar2(1);',
'   x number := 0;',
'   r varchar2(4000) := null;',
'begin',
'for c1 in (',
'with build_opts as (',
'    select build_option_name,',
'        build_option_status',
'    from apex_application_build_options',
'    where application_id = v(''APP_ID'')',
')',
'select',
'    sum(the_score) s,',
'    sum(max_value) m',
'from',
'    (',
'        select  ''Project has an owner'' metric,',
'            case when exists (select null',
'                              from eba_proj_user_ref rf,',
'                                  eba_proj_status_users u',
'                              where rf.project_id = p.id',
'                                  and rf.user_id = u.id',
'                                  and eba_proj_fw.is_edit_authorized( u.username, rf.project_id ) = ''Y''',
'                             )',
'                    then 20 else 0 end as the_score,',
'                20 max_value',
'        from eba_proj_status p where id = p_project_id',
'        union all ',
'        select  ''Project has a URL'' metric, ',
'                decode(url,null,0,10) the_score,',
'                10 max_value',
'        from eba_proj_status where id = p_project_id',
'        union all ',
'        select  ''Project has a goal'' metric, ',
'                decode(goal,null,0,20) the_score,',
'                20 max_value',
'        from eba_proj_status where id = p_project_id',
'        union all',
'        select  ''Project has a goal longer then 200 characters'' metric, ',
'                decode(goal,null,0,10) the_score,',
'                10 max_value',
'        from eba_proj_status where id = p_project_id and nvl(length(goal),0) >= 200',
'        union all ',
'        select  ''Project has description longer then 200 characters'' metric, ',
'                decode(description,null,0,10) the_score,',
'                10 max_value ',
'        from eba_proj_status where id = p_project_id and nvl(length(description),0) >= 200',
'        union all ',
'        select  ''Project has tags'' metric, ',
'                decode(s.tags,null,0,10) the_score,',
'                10 max_value ',
'        from eba_proj_status s where id = p_project_id',
'        union all ',
'        select  ''Project has description'' metric, ',
'                decode(description,null,0,20) the_score,',
'                20 max_value ',
'        from eba_proj_status where id = p_project_id',
'        union all',
'        select  nvl(max(''Project has milestones''),''Project has milestones'') metric, ',
'                decode(count(*),0,0,20) the_score,',
'                nvl(max(20),20) max_value ',
'        from EBA_PROJ_STATUS_MS m,',
'            build_opts bo',
'        where  m.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Milestones''',
'            and bo.build_option_status = ''Include''',
'        union all',
'        select  nvl(max(''Project has milestones past due (deduction)''),''Project has milestones past due (deduction)'') metric, ',
'                decode(count(*),0,0,-50) the_score,',
'                nvl(max(0),0) max_value ',
'        from EBA_PROJ_STATUS_MS m,',
'            build_opts bo',
'        where  m.project_id = p_project_id and m.milestone_status = ''Open'' and milestone_date < current_date',
'            and bo.build_option_name = ''Project Milestones''',
'            and bo.build_option_status = ''Include''',
'        union all',
'        select  nvl(max(''Project has links''),''Project has links'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from EBA_PROJ_STATUS_LINKS l,',
'            build_opts bo',
'        where l.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Links''',
'            and bo.build_option_status = ''Include''',
'        union all',
'        select  nvl(max(''Project has issues''),''Project has issues'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from EBA_PROJ_STATUS_ISSUES i,',
'            build_opts bo',
'        where i.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Issues''',
'            and bo.build_option_status = ''Include''',
'        union all',
'        select  nvl(max(''Project has resources''),''Project has resources'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from EBA_PROJ_RESOURCES r,',
'            build_opts bo',
'        where r.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Resources''',
'            and bo.build_option_status = ''Include''',
'        union all',
'        select  nvl(max(''Project has action items''),''Project has action items'') metric, ',
'                decode(count(*),0,0,20) the_score,',
'                nvl(max(20),20) max_value ',
'        from EBA_PROJ_STATUS_AIS a,',
'            build_opts bo',
'        where a.project_id = p_project_id',
'            and bo.build_option_name = ''Project Action Items''',
'        union all',
'        select  nvl(max(''Project has action items past due (deduction)''),''Project has action items pastdue (deduction)'') metric, ',
'                decode(count(*),0,0,-50) the_score,',
'                nvl(max(0),0) max_value ',
'        from EBA_PROJ_STATUS_AIS a,',
'            build_opts bo',
'        where a.project_id = p_project_id',
'            and action_status = ''Open''',
'            and due_date < current_date',
'            and bo.build_option_name = ''Project Action Items''',
'        union all',
'        select  nvl(max(''Project has project updates''),''Project has project updates'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from eba_proj_status_updates u,',
'            build_opts bo',
'        where  u.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Updates''',
'        union all',
'        select  nvl(max(''Project has project updates in last week''),''Project has project updates in last week'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from EBA_PROJ_STATUS_UPDATES u,',
'            build_opts bo',
'        where  u.project_id = p_project_id  and UPDATE_DATE > (sysdate - 7)',
'            and bo.build_option_name = ''Project Updates''',
'        union all',
'        select  nvl(max(''Project has attachments''),''Project has attachments'') metric, ',
'                decode(count(*),0,0,5) the_score,',
'                nvl(max(5),5) max_value ',
'        from EBA_PROJ_STATUS_FILES u,',
'            build_opts bo',
'        where  u.project_id = p_project_id ',
'            and bo.build_option_name = ''Project Attachments''',
'        union all',
'        select  nvl(max(''Project has status reports''),''Project has status reports'') metric, ',
'                decode(count(*),0,0,10) the_score,',
'                nvl(max(10),10) max_value ',
'        from eba_proj_status_rpts u,',
'            build_opts bo',
'        where project_id = p_project_id',
'            and bo.build_option_name = ''Project Status Reports''',
'        union all',
'        select  nvl(max(''Project status is not desirable''),''Project statusis not desirable'') metric, ',
'                decode(count(*),0,0,-20) the_score,',
'                nvl(max(0),0) max_value ',
'        from eba_proj_status s , EBA_PROJ_STATUS_CODES c',
'        where s.id = p_project_id and s.PROJECT_STATUS = c.id and nvl(c.is_desirable_yn,''Y'') = ''N''',
'        union all',
'        select  nvl(max(''Project has been validated''),''Project has been validated'') metric, ',
'                decode(max((',
'                    select count(*)',
'                    from eba_proj_status_verifications v',
'                    where v.project_id = p_project_id )),0,0,20) the_score,',
'                nvl(max(20),20) max_value ',
'        from eba_proj_status,',
'            build_opts bo',
'        where id = p_project_id',
'            and bo.build_option_name = ''Project Validations''',
'        union all',
'        select  nvl(max(''Project has been validated in last week''),''Project has been validated in last week'') metric, ',
'                decode(max((',
'                    select count(*)',
'                    from eba_proj_status_verifications v',
'                    where v.project_id = p_project_id',
'                        and v.created > (sysdate - 7))),0,0,30) the_score,',
'                nvl(max(30),30) max_value ',
'        from eba_proj_status,',
'            build_opts bo',
'        where id = p_project_id',
'            and bo.build_option_name = ''Project Validations''',
'        union all',
'        select ''Project has been validated in last week by project owner'' metric, ',
'            case when exists (  select null',
'                                from eba_proj_user_ref rf,',
'                                    eba_proj_status_users u,',
'                                    eba_proj_status_verifications v',
'                                where rf.project_id = p.id',
'                                    and rf.user_id = u.id',
'                                    and eba_proj_fw.is_edit_authorized( u.username, rf.project_id ) = ''Y''',
'                                    and v.project_id = p.id',
'                                    and v.created > (sysdate-7)',
'                                    and upper(v.verified_by) = upper(u.username)',
'                             )',
'                then 30 else 0 end as the_score,',
'            30 max_value ',
'        from eba_proj_status p,',
'            build_opts bo',
'        where id = p_project_id',
'            and bo.build_option_name = ''Project Validations''',
'    ) x',
') loop',
'   l_project_score := c1.s;',
'   l_max_value := c1.m;',
'end loop;',
'   if NVL(l_project_score,0) > 0 and NVL(l_max_value,0) > 0 then',
'      x := round(100*(l_project_score/l_max_value));',
'   end if;',
'   if x > 100 then x := 100; end if;',
'   if x < 0 then x := 0; end if;',
'   if upper(trim(p_format)) = ''NUMBER'' then ',
'      return to_char(x);',
'   end if;',
'   for c1 in (select IS_CLOSED_STATUS, IS_ACTIVE_YN ',
'             from EBA_PROJ_STATUS_CODES ',
'             where id = (select max(PROJECT_STATUS) ',
'                         from EBA_PROJ_STATUS',
'                     where id = p_project_id)) loop',
'        l_closed := c1.IS_CLOSED_STATUS;',
'        l_active := c1.IS_ACTIVE_YN;',
'   end loop;',
'   if upper(trim(p_format)) = ''HTML'' then',
'       if NVL(l_closed,''0'') = ''Y'' then',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-null w100p">N/A</span>'';',
'       elsif NVL(l_active,''0'') = ''N'' then',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-null w100p">N/A</span>'';',
'       elsif x >= 95 then',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-success w100p">Very Strong</span>'';',
'       elsif x >= 66 then ',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-success w100p">Strong</span>'';',
'       elsif x >= 33 then',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-warning w100p">Moderate</span>'';',
'       elsif x >= 1 then ',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-danger w100p">Weak</span>'';',
'       else',
'          r :=  ''<span class="t-Badge t-Badge--basic t-Badge--small is-danger w100p">Very Weak</span>'';',
'       end if;',
'   else',
'       if NVL(l_closed,''0'') = ''Y'' then',
'          r :=  ''N/A'';',
'       elsif NVL(l_active,''0'') = ''N'' then',
'          r :=  ''N/A'';',
'       elsif x >= 95 then',
'          r :=  ''Very Strong'';',
'       elsif x >= 66 then ',
'          r :=  ''Strong'';',
'       elsif x >= 33 then',
'          r :=  ''Moderate'';',
'       elsif x >= 1 then ',
'          r :=  ''Weak'';',
'       else',
'          r :=  ''Very Weak'';',
'       end if;',
'   end if;',
'   return  r;',
'     ',
'end eba_proj_stat_get_con_comp;',
'/'))
);
end;
/
prompt --application/deployment/install/install_email_send_jobs
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(11958275559711683883)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Email Send Jobs'
,p_sequence=>880
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_schema          varchar2(30);',
'    l_program         varchar2(30)                   := ''EBA_PROJ_EMAIL_PAST_DUE_PRG'';',
'    l_job             varchar2(30)                   := ''EBA_PROJ_EMAIL_PAST_DUE_JOB'';',
