'                                 select f.content_id from eba_proj_status_favorites f where upper(f.user_name) = upper(u.username) and f.content_id = p.id and f.content_type = ''PROJECT''',
'                                )',
'                    )',
'                )',
'            and',
'                (',
'                    instr(u.username,''@'') > 0',
'                    or',
