 p_id=>wwv_flow_api.id(1784472045148336671)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_help package body'
,p_sequence=>930
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package body eba_proj_help as',
'    function get_project_details_help_text(',
