'',
'        if apex_util.get_build_option_status(',
'              p_application_id    => p_app_id,',
'              p_build_option_name => ''Project Updates''',
'           ) = ''INCLUDE'' then',
'            l_help_text := l_help_text || ''<li>Add/Manage Updates</li>'';',
