prompt --application/deployment/install/upgrade_eba_proj_status_show_detail_procedure
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(11916786868038770246)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_status_show_detail procedure'
,p_sequence=>970
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace procedure eba_proj_status_show_detail (p_project_id in number, p_app_id in number, p_app_session in number) is',
'    c              pls_integer := 0;',
'    l_last_project varchar2(500) := ''ZZZ'';',
'',
'    function get_milestone_name (p_id in number) return varchar2 is',
'        r varchar2(32767) := null;',
'    begin',
'        for c1 in ( select milestone_name',
'                    from   eba_proj_status_ms',
'                    where  project_id = p_id and milestone_status = ''Open''',
'                    order  by milestone_date desc) loop',
'            r := c1.milestone_name;',
'            exit;',
'        end loop;',
'        return apex_escape.html(r);',
'    end;',
'',
'    function get_next_ai (p_id in number) return varchar2 is',
'        r varchar2(5000) := null;',
'    begin',
'        for c1 in ( select action , due_date',
'                    from   eba_proj_status_ais',
'                    where  project_id = p_id and action_status = ''Open''',
'                    order  by due_date desc) loop',
'            r := apex_escape.html(c1.ACTION)||''<br />Due: ''||to_char(c1.due_date,''Day Month DD, YYYY'')||'' - ''||apex_util.get_since(c1.due_date);',
'            exit;',
'        end loop;',
'        return r;',
'    end;',
'',
'    function get_last_status (p_id in number) return varchar2 is',
'        r varchar2(32767) := null;',
'    begin',
'        for c1 in ( select status_update, created, created_by',
'                    from   eba_proj_status_updates',
'                    where  project_id = p_id',
'                    order  by created desc ) loop',
'            r := apex_escape.html(dbms_lob.substr(c1.status_update,500,1))||''<br />Contributed: ''||to_char(c1.CREATED,''Day Month DD, YYYY'')||'' - ''||apex_util.get_since(c1.CREATED)||'' by ''||apex_escape.html(lower(c1.created_by));',
'            exit;',
'        end loop;',
'        return r;',
'    end;',
'begin',
'    for c1 in ( select (select min(milestone_date)',
'                        from eba_proj_status_ms x',
'                        where x.project_id = p.id',
'                            and x.milestone_status = ''Open'') next_milestone_date,',
'                    p.id project_id,',
'                    p.row_key,',
'                    p.project,',
'                    decode(p.cat_id,null,null,',
'                        (   select category',
'                            from eba_proj_status_cats x',
'                            where x.id = p.cat_id)) proj_cat,',
'                    s.status_short_desc status_text,',
'                    (   select listagg(lower(u.username),'', '') within group',
'                            (order by nvl(rf.acl_status_level,r.default_acl_status_level) desc, lower(u.username))',
'                        from eba_proj_user_ref rf,',
'                            eba_proj_status_users u,',
'                            eba_proj_roles r',
'                        where rf.project_id = s.id',
'                            and rf.user_id = u.id',
'                            and rf.role_id = r.id',
'                            and eba_proj_fw.is_edit_authorized( u.username, rf.project_id ) = ''Y'' ) as owner,',
'                    (   select count(*)',
'                        from eba_proj_status_ais a',
'                        where a.project_id = p.id',
'                            and a.action_status = ''Open'') action_items,',
'                    (   select count(*)',
'                        from eba_proj_status_ms m',
'                        where m.project_id = p.id',
'                            and m.milestone_status = ''Open'') open_milestones,',
'                    decode(parent_project_id,null,null,',
'                        (   select project',
'                            from eba_proj_status x',
'                            where x.id = p.parent_project_id)) parent_project,',
'                    (   select count(*)',
'                        from eba_proj_status_updates x',
'                        where x.project_id = p.id ) status_updates,',
'                    p.parent_project_id,',
'                    (   select count(*)',
'                        from eba_proj_status x',
'                        where x.parent_project_id = p.id ) child_projects,',
'                    p.tags,',
'                    p.goal,',
'                    p.created,',
'                    p.created_by,',
'                    p.updated,',
'                    p.updated_by',
'                from eba_proj_status p,',
'                    eba_proj_status_codes s',
'                where p.project_status = s.id(+)',
'                    and p.id = p_project_id ) loop',
'        c := c + 1;',
'',
'        sys.htp.prn(''<div class="ctPDetails">'');',
'        sys.htp.prn(''<h3><a href="'');',
'        sys.htp.prn(apex_util.prepare_url(''f?p=''||p_app_id||'':200:''||p_app_session||''::NO:200:P200_ID:''||c1.project_id));',
'        sys.htp.prn(''">''||apex_escape.html(c1.project)||''</a></h3><ul>'');',
'',
'        sys.htp.prn(''<li>'');',
'        sys.htp.prn(''<table cellspacing="0" cellpadding="0" summary="">'');',
'',
'        if c1.proj_cat is not null then',
'            sys.htp.prn(''<tr><th>Category</th><td>''||apex_escape.html(c1.proj_cat)||''</td></tr>'');',
'        end if;',
'        if c1.parent_project is not null then',
'            sys.htp.prn(''<tr><th>Parent Project</th><td>''||apex_escape.html(c1.parent_project)||''</td></tr>'');',
'        end if;',
'        if c1.child_projects > 0 then',
'            sys.htp.prn(''<tr><th>Child Projects</th><td>''||to_char(c1.child_projects,''999G990'')||''</td></tr>'');',
'        end if;',
'',
'        sys.htp.prn(''<tr><th>Owner(s)</th><td>''||apex_escape.html(c1.owner)||''</td></tr>'');',
'        sys.htp.prn(''<tr><th>Status</th><td>''||apex_escape.html(c1.status_text)||''</td></tr>'');',
'        sys.htp.prn(''<tr><th>Goal</th><td>''||apex_escape.html(c1.goal)||''</td></tr>'');',
'        if c1.tags is not null then',
'            sys.htp.prn(''<tr><th>Tags</th><td>''||apex_escape.html(c1.tags)||''</td></tr>'');',
'        end if;',
'        if c1.open_milestones = 0 then',
'            sys.htp.prn(''<tr><th>Milestones</th><td>None defined, '');',
'            sys.htp.prn(''<a href="''||apex_util.prepare_url(''f?p=''||p_app_id||'':200:''||p_app_session||''::NO:200:P200_ID:''||c1.project_id)||''">'');',
'            sys.htp.prn(''create milestone</a>'');',
'        else',
'            sys.htp.prn(''<tr><th>''',
'                ||to_char(c1.open_milestones,''999G990'')',
'                ||'' Open Milestones</th><td>'');',
'            sys.htp.prn(''Next Milestone: ''||get_milestone_name(c1.project_id)||''<br />''',
'                ||to_char(c1.NEXT_MILESTONE_DATE,''Day Month DD, YYYY'')||'' - ''',
'                ||apex_util.get_since(c1.NEXT_MILESTONE_DATE));',
'            sys.htp.prn(''.  View <a href="''||apex_util.prepare_url(''f?p=''||p_app_id||'':68:''||p_app_session||'':::68:P68_PROJECT:''',
'                ||c1.project_id)||''">Gantt</a> or '');',
'            sys.htp.prn('' <a href="''||apex_util.prepare_url(''f?p=''||p_app_id||'':34:''||p_app_session||'':::34,200:P200_ID,P34_ID:''',
'                ||c1.project_id||'',''||c1.project_id)||''">timeline</a>.'');',
'            sys.htp.prn(''</td></tr>'');',
'        end if;',
'        if c1.action_items != 0 then',
'            sys.htp.prn(''<tr><th>''',
'                ||to_char(c1.action_items,''999G990'')||'' Open Action Items</th><td>''',
'                ||''Next Action: ''||get_next_ai(c1.project_id)',
'                ||''</td></tr>'');',
'        end if;',
'        if c1.status_updates != 0 then',
'            sys.htp.prn(''<tr><th>''||to_char(c1.status_updates,''999G990'')||'' Status Updates</th>''',
'                ||''<td>Most Recent:<br />''||get_last_status(c1.project_id)',
'                ||''</td></tr>'');',
'        end if;',
'        sys.htp.prn(''<tr><th>Timestamps</th><td>Created ''||apex_util.get_since(c1.created)||'' by ''',
'            ||apex_escape.html(lower(c1.created_by))',
'            ||''<br />Updated ''||apex_util.get_since(c1.updated)||'' by ''',
'            ||apex_escape.html(lower(c1.updated_by))||''</td></tr>'');',
'        sys.htp.prn(''</table>'');',
'        l_last_project := c1.project;',
'    end loop; -- c1',
'    sys.htp.prn(''</ul>'');',
'    sys.htp.prn(''<div class="clear"></div>'');',
'    sys.htp.prn(''</div>'');',
'end eba_proj_status_show_detail;',
'/',
'show errors'))
);
end;
/
prompt --application/deployment/install/upgrade_eba_proj_flex_fw_package_body
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(6109547272255239907)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_flex_fw package body'
,p_sequence=>980
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package body eba_proj_flex_fw as',
'',
'    procedure flex_report_update (',
'        p_flex_table_name      in     varchar2,',
'        p_irr_region_id        in     number,',
'        p_flex_column_prefix   in     varchar2,',
'        p_app_id               in     number,',
'        p_page_id              in     number,',
'        p_region_type          in     varchar2',
'    )',
'    is',
'        type postfixes_t is table of varchar2(30);',
'        l_postfixes postfixes_t',
'            := postfixes_t( ''_FLEX_01'',''_FLEX_02'',''_FLEX_03'',''_FLEX_04'',',
'                            ''_FLEX_05'',''_FLEX_06'',''_FLEX_07'',''_FLEX_08'',',
'                            ''_FLEX_N01'',''_FLEX_N02'',''_FLEX_N03'',''_FLEX_N04'',',
'                            ''_FLEX_D01'',''_FLEX_D02'',''_FLEX_D03'',''_FLEX_D04'',',
'                            ''_FLEX_CLOB'' );',
'',
'        l_interactive_report_id number;',
'        l_region_id             number;',
'        l_label                 varchar2(255);',
'        l_alias                 varchar2(255);',
'        l_display_in_irr        varchar2(1);',
'        l_is_active             varchar2(1);',
'        l_format_mask           varchar2(30);',
'        l_rpt_hdr_alignment     varchar2(30);',
'        l_lov_type              varchar2(30);',
'        l_lov_sql_query         varchar2(4000);',
'        l_condition_type        varchar2(255);',
'        l_condition1            varchar2(4000);',
'        l_condition2            varchar2(4000);',
'        l_allow_sorting         varchar2(1) := ''N'';',
'        l_allow_filtering       varchar2(1) := ''N'';',
'        l_allow_highlighting    varchar2(1) := ''N'';',
'        l_allow_ctrl_breaks     varchar2(1) := ''N'';',
'        l_allow_aggregations    varchar2(1) := ''N'';',
'        l_allow_computations    varchar2(1) := ''N'';',
'        l_allow_charting        varchar2(1) := ''N'';',
'        l_allow_group_by        varchar2(1) := ''N'';',
'        l_allow_hide            varchar2(1) := ''N'';',
'        --',
'',
'        function get_irr_column_id(',
'            p_app_id     in     number,',
'            p_page_id     in     number,',
'            p_flex_column in     varchar2',
'        ) return number',
'        is',
'        begin',
'            for c1 in ( select arc.column_id',
'                        from apex_application_page_ir_col arc',
'                        where arc.application_id = p_app_id',
'                            and arc.page_id = p_page_id',
'                            and arc.column_alias = p_flex_column ) loop',
'                return c1.column_id;',
'            end loop;',
'            return null;',
'        end get_irr_column_id;',
'',
'    begin',
'        apex_app_builder_api.set_application_id (p_application_id => apex_application.g_flow_id);',
'        if p_region_type = ''IR'' then',
'            for c1 in (select i.interactive_report_id',
'                       from apex_application_page_regions r, apex_application_page_ir i',
'                       where r.application_id = i.application_id',
'                           and r.page_id = i.page_id',
'                           and r.region_id = i.region_id',
'                           and r.application_id = p_app_id',
'                           and r.page_id = p_page_id',
'                           and r.region_id = p_irr_region_id) loop',
'                l_interactive_report_id := c1.interactive_report_id;',
'            end loop;',
'        else',
'            for c1 in (select region_id',
'                       from apex_application_page_regions',
'                       where application_id = p_app_id',
'                           and page_id = p_page_id',
'                           and region_id = p_irr_region_id) loop',
'                l_region_id := c1.region_id;',
'            end loop;',
'        end if;',
'',
'        -- Flex Columns',
'        for pf in 1..l_postfixes.COUNT loop',
'            l_label := null;',
'            l_alias := p_flex_column_prefix || l_postfixes(pf);',
'            for c2 in ( select substr(allow_sorting,1,1) as allow_sorting,',
'                            substr(allow_filtering,1,1) as allow_filtering,',
'                            substr(allow_highlighting,1,1) as allow_highlighting,',
'                            substr(allow_ctrl_breaks,1,1) as allow_ctrl_breaks,',
'                            substr(allow_aggregations,1,1) as allow_aggregations,',
'                            substr(allow_computations,1,1) as allow_computations,',
'                            substr(allow_charting,1,1) as allow_charting,',
'                            substr(allow_group_by,1,1) as allow_group_by,',
'                            substr(allow_hide,1,1) as allow_hide',
'                        from apex_application_page_ir_col',
'                        where interactive_report_id = l_interactive_report_id',
'                            and column_alias = l_alias ) loop',
'                l_allow_sorting      := c2.allow_sorting;',
'                l_allow_filtering    := c2.allow_filtering;',
'                l_allow_highlighting := c2.allow_highlighting;',
'                l_allow_ctrl_breaks  := c2.allow_ctrl_breaks;',
'                l_allow_aggregations := c2.allow_aggregations;',
'                l_allow_computations := c2.allow_computations;',
'                l_allow_charting     := c2.allow_charting;',
'                l_allow_group_by     := c2.allow_group_by;',
'                l_allow_hide         := c2.allow_hide;',
'            end loop;',
'',
'            for c1 in ( select nvl(fr.report_label_text, fr.form_label_text) label,',
'                            fr.is_displayed_on_ir,',
'                            fr.format_mask,',
'                            fr.rpt_hdr_alignment,',
'                            case when fr.display_as = ''SELECT_LIST'' then fr.lov_type',
'                                else null',
'                            end as lov_type,',
'                            case when fr.display_as = ''SELECT_LIST'' then',
'                                case fr.lov_type',
'                                    when ''STATIC'' then',
'                                        ''STATIC2(~,*):''',
'                                            ||( select listagg(display_value||''*''||return_value,''~'')',
'                                                    within group ( order by display_sequence )',
'                                                from eba_proj_flex_static_lovs sl',
'                                                where sl.flex_table = fr.flexible_table',
'                                                    and sl.flex_column = fr.flexible_column )',
'                                    when ''DYNAMIC'' then',
'                                        dbms_lob.substr(fr.lov_sql_query,4000,1)',
'                                    else',
'                                        null',
'                                end',
'                                else null',
'                            end as lov_sql_query,',
'                            fr.condition_type,',
'                            fr.condition1,',
'                            fr.condition2,',
'                            fr.active_yn',
'                        from eba_proj_flex_registry fr',
'                        where fr.flexible_table = p_flex_table_name',
'                            and fr.flexible_column = l_alias ) loop',
'                l_label             := c1.label;',
'                l_display_in_irr    := c1.is_displayed_on_ir;',
'                l_format_mask       := c1.format_mask;',
'                l_rpt_hdr_alignment := c1.rpt_hdr_alignment;',
'                -- If the LOV query is undefined, then there is no LOV.',
'                l_lov_type          := case when c1.lov_sql_query is null then null else c1.lov_type end;',
'                l_lov_sql_query     := c1.lov_sql_query;',
'                l_condition_type    := c1.condition_type;',
'                l_condition1        := c1.condition1;',
'                l_condition2        := c1.condition2;',
'                l_is_active         := c1.active_yn;',
'            end loop;',
'',
'            if p_region_type = ''IR'' and l_label is not null then',
'                apex_app_builder_api.edit_ir_column (',
'                    p_id                     => get_irr_column_id(',
'                                                    p_app_id      => p_app_id,',
'                                                    p_page_id     => p_page_id,',
'                                                    p_flex_column => l_alias),',
'                    p_page_id                => p_page_id,',
'                    p_interactive_report_id  => l_interactive_report_id,',
'                    --',
'                    p_column_label           => l_label,',
'                    p_display_text_as        => case',
'                                                    when l_is_active = ''Y'' then ''ESCAPE_SC''',
'                                                    else ''HIDDEN''',
'                                                end,',
'                    p_rpt_show_filter_lov    => ''D'',',
'                    p_rpt_lov                => null,',
'                    p_display_in_default_rpt => l_display_in_irr,',
'                    p_heading_alignment      => l_rpt_hdr_alignment,',
'                    --',
'                    p_allow_sorting          => l_allow_sorting,',
'                    p_allow_filtering        => l_allow_filtering,',
'                    p_allow_highlighting     => l_allow_highlighting,',
'                    p_allow_ctrl_breaks      => l_allow_ctrl_breaks,',
'                    p_allow_aggregations     => l_allow_aggregations,',
'                    p_allow_computations     => l_allow_computations,',
'                    p_allow_charting         => l_allow_charting,',
'                    p_allow_group_by         => l_allow_group_by,',
'                    p_allow_hide             => l_allow_hide,',
'                    --',
'                    p_format_mask            => l_format_mask,',
'                    p_column_link            => null,',
'                    p_column_linktext        => null,',
'                    p_column_link_attr       => null,',
'                    p_display_condition_type => l_condition_type,',
'                    p_display_condition      => l_condition1,',
'                    p_display_condition2     => l_condition2',
'                    );',
'            elsif p_region_type = ''CR'' and l_label is not null and l_is_active = ''Y'' then',
'                apex_app_builder_api.edit_cr_column (',
'                    p_page_id                 => p_page_id,',
'                    p_region_id               => l_region_id,',
'                    p_column_alias            => l_alias,',
'                    p_column_label            => l_label,',
'                    p_heading_alignment       => l_rpt_hdr_alignment,',
'                    --',
'                    p_display_as              => case when l_lov_type is not null then ''TEXT_FROM_LOV''',
'                                                    else ''ESCAPE_SC''',
'                                                end,',
'                    p_inline_lov              => l_lov_sql_query,',
'                    --',
'                    p_display_when_cond_type  => l_condition_type,',
'                    p_display_when_condition  => l_condition1,',
'                    p_display_when_condition2 => l_condition2);',
'            end if;',
'',
'        end loop;',
'    end flex_report_update;',
'',
'    function validate_lov_query ( p_query in varchar2,',
'                                  p_display_column out varchar2,',
'                                  p_return_column out varchar2,',
'                                  p_error out varchar2',
'                                ) return boolean is',
'        l_source_query  varchar2(32767) := p_query;',
'        l_source_queryv varchar2(32767);',
'        l_report_cursor integer;',
'        --',
'        l_col_cnt number;',
'        l_cols    sys.dbms_sql.desc_tab2;',
'',
'        function clean_query( p_query in varchar2 ) return varchar2 is',
'            l_query varchar2(32767) := p_query;',
'        begin',
'            loop',
'                if substr(l_query,-1) in (chr(10),chr(13),'';'','' '',''/'') then',
'                    l_query := substr(l_query,1,length(l_query)-1);',
'                else',
'                    exit;',
'                end if;',
'            end loop;',
'            return l_query;',
'        end clean_query;',
'        --',
'    begin',
'        if l_source_query is not null then',
'            if substr(upper(ltrim(l_source_query)),1,6) != ''SELECT''',
'                    and substr(upper(ltrim(l_source_query)),1,4) != ''WITH'' then',
'                p_error := ''Query must begin with SELECT or WITH'';',
'            else',
'                l_source_query := clean_query( l_source_query );',
'                l_source_queryv := sys.dbms_assert.noop( str => l_source_query );',
'                begin',
'                    l_report_cursor := sys.dbms_sql.open_cursor;',
'                    sys.dbms_sql.parse( l_report_cursor, l_source_queryv, SYS.DBMS_SQL.NATIVE );',
'                    sys.dbms_sql.describe_columns2( l_report_cursor, l_col_cnt, l_cols );',
'                    sys.dbms_sql.close_cursor(l_report_cursor);',
'                    if l_col_cnt = 2 then',
'                        if l_cols(1).col_name_len > 30 or l_cols(2).col_name_len > 30 then',
'                            p_error := ''Column name too long; please use an alias'';',
'                        else',
'                            p_display_column := l_cols(1).col_name;',
'                            p_return_column  := l_cols(2).col_name;',
'                            p_error := null;',
'                        end if;',
'                    else',
'                        p_error := ''Select List Query must have two columns'';',
'                    end if;',
'                exception when others then',
'                    if sys.dbms_sql.is_open( l_report_cursor ) then',
'                        sys.dbms_sql.close_cursor( l_report_cursor );',
'                    end if;',
'                    p_error := sqlerrm;',
'                end;',
'            end if;',
'        else',
'            p_error := ''Select List Query must have some value'';',
'        end if;',
'',
'        if p_error is null then',
'            return true;',
'        else',
'            return false;',
'        end if;',
'    end validate_lov_query;',
'',
'    procedure populate_page_map_table',
'    is',
'        l_region_type varchar2(10);',
'        l_prefix      varchar2(30);',
'        l_app_id      number;',
'        --',
'        l_classes     apex_application_global.vc_arr2;',
'    begin',
'        l_app_id := nvl(apex_application_install.get_application_id,v(''APP_ID''));',
'',
'        -- Clear out any page mapping data that already exists, as it may be outdated now.',
'        delete from eba_proj_flex_page_map;',
'',
'        for c1 in ( select r.page_id,',
'                        r.region_css_classes,',
'                        r.source_type_code,',
'                        r.region_id',
'                    from apex_application_page_regions r,',
'                        apex_application_pages p',
'                    where r.application_id = l_app_id',
'                        and r.application_id = p.application_id',
'                        and r.page_id = p.page_id',
'                        and r.source_type_code in (''DYNAMIC_QUERY'',''SQL_QUERY'',''STATIC_TEXT'')',
'                        and upper(r.region_css_classes) like ''%FLEX%''',
'                ) loop',
'            --Determine region type',
'            if c1.source_type_code = ''DYNAMIC_QUERY'' then',
'                l_region_type := ''IR'';',
'            elsif c1.source_type_code = ''SQL_QUERY'' then',
'                l_region_type := ''CR'';',
'            elsif c1.source_type_code = ''STATIC_TEXT'' then',
'                l_region_type := ''FORM'';',
'            end if;',
'',
'            l_classes := apex_util.string_to_table(lower(c1.region_css_classes),'' '');',
'            for i in 1..l_classes.COUNT loop',
'                for c2 in ( select flexible_table, table_prefix',
'                            from eba_proj_flex_registry',
'                            where report_css_class = l_classes(i)',
'                            group by flexible_table, table_prefix ) loop',
'                    insert into eba_proj_flex_page_map',
'                        ( flex_table, page_id, region_id, flex_column_prefix, region_type )',
'                    values',
'                        ( c2.flexible_table, c1.page_id, c1.region_id, c2.table_prefix, l_region_type );',
'                end loop;',
'            end loop;',
'        end loop;',
'    end populate_page_map_table;',
'',
'    procedure reset_flex_registry is',
'    begin',
'        -- Update all flex registry columns to factory defaults',
'        update eba_proj_flex_registry',
'        set friendly_name      = null,',
'            assigned_yn        = ''N'',',
'            active_yn          = ''N'',',
'            form_label_text    = flexible_column,',
'            report_label_text  = null,',
'            is_required_yn     = ''N'',',
'            is_displayed_on_ir = ''N'',',
'            label_template_id  = 0,',
'            display_as         = ''TEXT'',',
'            width              = 30,',
'            max_width          = 4000,',
'            height             = 1,',
'            format_mask        = null,',
'            label_alignment    = null,',
'            help_text          = null,',
'            lov_type           = null,',
'            lov_sql_query      = null,',
'            default_value      = null,',
'            rpt_hdr_alignment  = null,',
'            condition_type     = ''EXISTS'',',
'            condition1         = ''select null from eba_proj_flex_registry ''',
'                                    ||''where flexible_table = ''''''',
'                                    ||flexible_table',
'                                    ||'''''' and flexible_column = ''''''',
'                                    ||flexible_column',
'                                    ||'''''' and active_yn = ''''Y''''''',
'                                    ||'' and assigned_yn = ''''Y'''''',',
'            condition2         = null;',
'',
'        -- Update CLOB flex registry columns to factory defaults',
'        update eba_proj_flex_registry',
'        set display_as  = ''TEXTAREA'',',
'            width       = 80,',
'            max_width   = 30000,',
'            height      = 5',
'        where instr(flexible_column,''FLEX_CLOB'') > 0;',
'    end reset_flex_registry;',
'',
'    function fetch_v( p_column in varchar2,',
'                      p_input in varchar2 ) return varchar2 is',
'        -- The return value. Set to the lookup value by default; if the column',
'        -- actually has a valid LOV, it will be replaced appropriately.',
'        l_val varchar2(4000) := p_input;',
'        -- Variables needed for dealing with dynamic LOVs.',
'        l_sql     clob;',
'        type ref_csr_t is ref cursor;',
'        l_refcsr  ref_csr_t;',
'    begin',
'        for c1 in ( select fr.lov_type,',
'                        fr.lov_sql_query,',
'                        fr.lov_display_col,',
'                        fr.lov_return_col',
'                    from eba_proj_flex_registry fr',
'                    where flexible_column = p_column ) loop',
'            if c1.lov_type = ''STATIC'' then',
'                for c2 in ( select display_value',
'                            from eba_proj_flex_static_lovs',
'                            where flex_column = p_column',
'                                and return_value = p_input ) loop',
'                    l_val := c2.display_value;',
'                end loop;',
'            elsif c1.lov_type = ''DYNAMIC'' then',
'                if c1.lov_sql_query is not null then',
'                    l_sql := ''select '' || sys.dbms_assert.enquote_name(str => c1.lov_display_col, capitalize => false) || '' from (''',
'                        || sys.dbms_assert.noop(str => c1.lov_sql_query)',
'                        || '') where '' || sys.dbms_assert.enquote_name(str => c1.lov_return_col, capitalize => false) || '' = ''',
'                        || sys.dbms_assert.enquote_literal(str => replace(p_input,'''''''',''''''''''''));',
'                    open l_refcsr for l_sql;',
'                    -- Normally, we would loop, but we expect just one row.',
'                    fetch l_refcsr into l_val;',
'                    close l_refcsr;',
'                end if;',
'            end if;',
'        end loop;',
'',
'        return l_val;',
'    end fetch_v;',
'',
'    function fetch_n( p_column in varchar2,',
'                      p_input in number ) return varchar2 is',
'        -- The return value. Set to the lookup value by default; if the column',
'        -- actually has a valid LOV, it will be replaced appropriately.',
'        l_val varchar2(4000);',
'        -- Variables needed for dealing with dynamic LOVs.',
'        l_sql     clob;',
'        type ref_csr_t is ref cursor;',
'        l_refcsr  ref_csr_t;',
'    begin',
'        for c1 in ( select fr.format_mask,',
'                        fr.lov_type,',
'                        fr.lov_sql_query,',
'                        fr.lov_display_col,',
'                        fr.lov_return_col',
'                    from eba_proj_flex_registry fr',
'                    where flexible_column = p_column ) loop',
'            l_val := to_char( p_input, c1.format_mask );',
'            if c1.lov_type = ''STATIC'' then',
'                for c2 in ( select display_value',
'                            from eba_proj_flex_static_lovs',
'                            where flex_column = p_column',
'                                and return_value = p_input ) loop',
'                    l_val := c2.display_value;',
'                end loop;',
'            elsif c1.lov_type = ''DYNAMIC'' then',
'                if c1.lov_sql_query is not null then',
'                    l_sql := ''select '' || sys.dbms_assert.enquote_name(str => c1.lov_display_col, capitalize => false) || '' from (''',
'                        || sys.dbms_assert.noop(str => c1.lov_sql_query)',
'                        || '') where '' || sys.dbms_assert.enquote_name(str => c1.lov_return_col, capitalize => false) || '' = ''',
'                        || sys.dbms_assert.enquote_literal(str => replace(p_input,'''''''',''''''''''''));',
'                    open l_refcsr for l_sql;',
'                    -- Normally, we would loop, but we expect just one row.',
'                    fetch l_refcsr into l_val;',
'                    close l_refcsr;',
'                end if;',
'            end if;',
'        end loop;',
'',
'        return l_val;',
'    end fetch_n;',
'',
'end eba_proj_flex_fw;',
'/',
'show errors'))
);
end;
/
prompt --application/deployment/install/upgrade_eba_proj_template_fw_body
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(13524607054823090676)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'eba_proj_template_fw body'
,p_sequence=>990
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package body eba_proj_template_fw as',
'',
'    function start_offset( p_milestone_id in number ) return number is',
'    begin',
'        for c1 in ( with ms_hier ( template_id, milestone_id, parent_milestone_id, start_date_offset, due_date_offset )',
'                    as (',
'                        select m.template_id,',
'                            m.id milestone_id,',
'                            m.parent_milestone_id,',
'                            m.start_date_offset,',
'                            m.due_date_offset',
'                        from eba_proj_template_ms m',
'                        where m.parent_milestone_id is null',
'                        union all',
'                        select m.template_id,',
'                            m.id milestone_id,',
'                            m.parent_milestone_id,',
'                            mh.start_date_offset + mh.due_date_offset start_date_offset,',
'                            m.due_date_offset',
'                        from eba_proj_template_ms m,',
'                            ms_hier mh',
'                        where mh.template_id = m.template_id',
'                            and mh.milestone_id = m.parent_milestone_id',
'                    )',
'                    select start_date_offset',
'                    from ms_hier',
'                    where milestone_id = p_milestone_id ) loop',
'            return c1.start_date_offset;',
'        end loop;',
'',
'        return 0;',
'    end start_offset;',
'',
'end eba_proj_template_fw;',
'/'))
);
end;
/
prompt --application/deployment/install/upgrade_seed_data
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(6003101645025229853)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'seed data'
,p_sequence=>1000
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package eba_proj_status_data_api as',
'    procedure load_look_up_data;',
'    procedure load_sample_data;',
'    procedure remove_sample_data;',
'end eba_proj_status_data_api;',
'/',
'show errors',
'',
'',
'create or replace package body eba_proj_status_data_api as',
'',
'    function varchar2_to_blob(p_varchar2_tab in dbms_sql.varchar2_table)',
'      return blob',
'    is',
'      l_blob blob;',
'      l_raw  raw(500);',
'      l_size number;',
'    begin',
'      dbms_lob.createtemporary(l_blob, true, dbms_lob.session);',
'      for i in 1 .. p_varchar2_tab.count loop',
'        l_size := length(p_varchar2_tab(i)) / 2;',
'        dbms_lob.writeappend(l_blob, l_size, hextoraw(p_varchar2_tab(i)));',
'      end loop;',
'      return l_blob;',
'    exception',
'      when others then',
'        dbms_lob.close(l_blob);',
'    end varchar2_to_blob;  ',
'',
'',
'    procedure load_look_up_data is',
'        l_image_prefix  varchar2(255);',
'    begin',
'        l_image_prefix := v(''IMAGE_PREFIX'');',
'',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (1, ''Prototype'', 1);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (2, ''Cloudification'', 2);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (3, ''Modernization'', 3);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (4, ''Research & Development'', 4);',
'        insert into eba_proj_status_cats (id, category, display_sequence) values (5, ''IT Operations'', 5);',
'        commit;',
'',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''RED'',''#D91E18'',l_image_prefix||''eba/img/status_indicator.png'',0,0, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''GREEN'',''#2ECC71'',l_image_prefix||''eba/img/status_indicator.png'',0,-80, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''YELLOW'',''#F1C40F'',l_image_prefix||''eba/img/status_indicator.png'',0,-40, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''BLACK'',''#303030'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''SILVER'',''#BDC3C7'',l_image_prefix||''eba/img/status_indicator.png'',0,-160, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''GRAY'',''#A0A0A0'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
'        insert into eba_proj_color_codes (color_name, color_code, sprite_url, sprite_position_x, sprite_position_y, display_sequence, is_active_yn) values (''ORANGE'',''#F39C12'',l_image_prefix||''eba/img/status_indicator.png'',0,-120, 1, ''Y'');',
