'                and a.action_status = ''Open''',
'                and a.is_deleted_yn = ''N''',
'                and (',
'                        p_user_email is null',
'                        or',
'                        lower(ow.email) = lower(p_user_email)',
'                    )',
'                and ow.email like ''%@%''',
'                and a.due_date between sysdate and sysdate + 7',
'                and ow.urs not in (''NEVER'',''UNSET'')',
'                and (',
'                        p_method != ''JOB''',
'                        or',
'                        (',
'                            ow.urs = ''QUARTERLY''',
