prompt --application/deployment/install/upgrade_add_issue_levels
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(94349981980816863)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Add Issue Levels'
,p_sequence=>1380
,p_script_type=>'UPGRADE'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>'select null from user_tables where table_name = ''EBA_PROJ_ISSUE_LEVELS'''
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Create the new issue level look-up table',
'create table eba_proj_issue_levels (',
'    id                     number primary key,',
'    name                   varchar2(255) unique not null,',
'    description            varchar2(4000),',
'    is_active_yn           varchar2(1),',
'    --',
'    created                timestamp(6) with local time zone,',
'    created_by             varchar2(255),',
'    updated                timestamp(6) with local time zone,',
'    updated_by             varchar2(255)',
')',
'/',
'',
'-- Create the new issue level biu trigger',
'create or replace trigger biu_eba_proj_issue_levels',
'    before insert or update on eba_proj_issue_levels',
'    for each row',
'begin',
'    if :new.id is null then',
'        :new.id := to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'');',
'    end if;',
'    if inserting then',
'        :new.created := localtimestamp;',
'        :new.created_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'    if inserting or updating then',
'        :new.updated := localtimestamp;',
'        :new.updated_by := nvl(wwv_flow.g_user,user);',
'    end if;',
'end;',
'/',
'',
'-- Enable the new issue category biu trigger',
'alter trigger biu_eba_proj_issue_levels enable',
'/',
'',
'-- Populate the issue category new look-up table',
'begin',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (1,''Critical'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (2,''Elevated'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (3,''Important'','''',''Y'');',
'    insert into eba_proj_issue_levels (id, name, description, is_active_yn) values (4,''Tracking'','''',''Y'');',
'end;',
'/'))
);
end;
/
prompt --application/deployment/install/upgrade_remove_text_search
begin
wwv_flow_api.create_install_script(
 p_id=>wwv_flow_api.id(964162633865330866)
,p_install_id=>wwv_flow_api.id(8877686581966151658)
,p_name=>'Remove Text Search'
,p_sequence=>1390
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    procedure drop_text_preference( p_pref_name in varchar2 ) is',
'    begin',
'        execute immediate ''begin ctx_ddl.drop_preference('''''' || p_pref_name || ''''''); end;'';',
'    exception when others then',
'        null;',
'    end drop_text_preference;',
'',
'begin',
'    -- Drop any old text indexes',
'    for c1 in ( select index_name',
'                from user_indexes',
'                where index_name in (',
'                    ''EBA_PROJ_STATUS_TXT1_IDX'',',
'                    ''EBA_PROJ_STATUS_TXT2_IDX'',',
'                    ''EBA_PROJ_AI_TXT_IDX'',',
'                    ''EBA_PROJ_FILES_TXT_IDX'',',
'                    ''EBA_PROJ_LINKS_TXT_IDX'',',
'                    ''EBA_PROJ_MS_TXT_IDX'',',
'                    ''EBA_PROJ_RPTS_TXT_IDX'',',
'                    ''EBA_PROJ_UPDATES_TXT_IDX'',',
'                    ''EBA_PROJ_USERS_TXT_IDX'',',
'                    ''EBA_PROJ_TAGS_TXT_IDX'',',
'                    ''EBA_PROJ_ISSUES_TXT_IDX'',',
'                    ''EBA_PROJ_RES_TXT_IDX''',
'                    )) loop',
'        execute immediate ''drop index ''||c1.index_name;',
'    end loop;',
'',
'    drop_text_preference( ''eba_proj_status_multi'' );',
'    drop_text_preference( ''eba_proj_files_multi'' );',
'    drop_text_preference( ''eba_proj_links_multi'' );',
'    drop_text_preference( ''eba_proj_status_ms_multi'' );',
'    drop_text_preference( ''eba_proj_status_ais_multi'' );',
'    drop_text_preference( ''eba_proj_status_rpts_multi'' );',
'    drop_text_preference( ''eba_proj_status_iss_multi'' );',
'    drop_text_preference( ''eba_proj_status_res_multi'' );',
'    ',
'    -- drop the old package',
'    for c1 in (select ''x'' ',
'               from user_objects',
'               where object_type = ''PACKAGE''',
'               and   object_name = ''EBA_PROJ_TEXT''',
'              ) loop',
'        execute immediate ''drop package EBA_PROJ_TEXT'';',
'    end loop;',
'end;',
'/'))
);
end;
